INSERT INTO `doituong_kcb` (`id`, `ma`, `truong_hop`, `quy_dinh`, `muc_huong`, `ghi_chu`, `nguon`, `ngay_hieu_luc`, `is_active`, `created_at`, `updated_at`) VALUES
(71, '01', 'Khám bệnh', NULL, NULL, NULL, 'https://xaydungchinhsach.chinhphu.vn/quy-dinh-danh-muc-ma-kham-chua-benh-va-ma-khoa-phuc-vu-ket-noi-du-lieu-bhyt-119260630165800133.htm', '2026-08-01', 1, '2026-10-02 15:42:31', '2026-10-02 15:42:31'),
(72, '02', 'Điều trị ngoại trú', NULL, NULL, 'Điều trị ngoại trú các bệnh không thuộc các bệnh cần chữa trị dài ngày theo Phụ lục I Thông tư 25/2025/TT-BYT', 'https://xaydungchinhsach.chinhphu.vn/quy-dinh-danh-muc-ma-kham-chua-benh-va-ma-khoa-phuc-vu-ket-noi-du-lieu-bhyt-119260630165800133.htm', '2026-08-01', 1, '2026-10-02 15:42:31', '2026-10-02 15:42:31'),
(73, '03', 'Điều trị nội trú', NULL, NULL, 'Thời gian điều trị nội trú dưới 4 giờ thì sử dụng mã 09', 'https://xaydungchinhsach.chinhphu.vn/quy-dinh-danh-muc-ma-kham-chua-benh-va-ma-khoa-phuc-vu-ket-noi-du-lieu-bhyt-119260630165800133.htm', '2026-08-01', 1, '2026-10-02 15:42:31', '2026-10-02 15:42:31'),
(74, '04', 'Điều trị ban ngày', NULL, NULL, 'Không áp dụng cho trường hợp điều trị nội trú dưới 4 giờ (mã 09)', 'https://xaydungchinhsach.chinhphu.vn/quy-dinh-danh-muc-ma-kham-chua-benh-va-ma-khoa-phuc-vu-ket-noi-du-lieu-bhyt-119260630165800133.htm', '2026-08-01', 1, '2026-10-02 15:42:31', '2026-10-02 15:42:31'),
(75, '05', 'Điều trị ngoại trú các bệnh cần chữa trị dài ngày liên tục trong năm, có khám bệnh và lĩnh thuốc', NULL, NULL, 'Nếu có thực hiện dịch vụ kỹ thuật thì sử dụng mã 08', 'https://xaydungchinhsach.chinhphu.vn/quy-dinh-danh-muc-ma-kham-chua-benh-va-ma-khoa-phuc-vu-ket-noi-du-lieu-bhyt-119260630165800133.htm', '2026-08-01', 1, '2026-10-02 15:42:31', '2026-10-02 15:42:31'),
(76, '06', 'Lưu người bệnh tại phòng khám đa khoa, phòng khám đa khoa khu vực, nhà hộ sinh, trạm y tế xã, phường', NULL, NULL, NULL, 'https://xaydungchinhsach.chinhphu.vn/quy-dinh-danh-muc-ma-kham-chua-benh-va-ma-khoa-phuc-vu-ket-noi-du-lieu-bhyt-119260630165800133.htm', '2026-08-01', 1, '2026-10-02 15:42:31', '2026-10-02 15:42:31'),
(77, '07', 'Nhận thuốc theo hẹn', NULL, NULL, 'Không thuộc trường hợp người bệnh đi khám bệnh, chữa bệnh', 'https://xaydungchinhsach.chinhphu.vn/quy-dinh-danh-muc-ma-kham-chua-benh-va-ma-khoa-phuc-vu-ket-noi-du-lieu-bhyt-119260630165800133.htm', '2026-08-01', 1, '2026-10-02 15:42:31', '2026-10-02 15:42:31'),
(78, '08', 'Điều trị ngoại trú bệnh cần chữa trị dài ngày, có khám bệnh, thực hiện dịch vụ kỹ thuật và/hoặc sử dụng thuốc', NULL, NULL, NULL, 'https://xaydungchinhsach.chinhphu.vn/quy-dinh-danh-muc-ma-kham-chua-benh-va-ma-khoa-phuc-vu-ket-noi-du-lieu-bhyt-119260630165800133.htm', '2026-08-01', 1, '2026-10-02 15:42:31', '2026-10-02 15:42:31'),
(79, '09', 'Điều trị nội trú dưới 04 giờ', NULL, NULL, 'Không áp dụng cho trường hợp điều trị ban ngày (mã 04)', 'https://xaydungchinhsach.chinhphu.vn/quy-dinh-danh-muc-ma-kham-chua-benh-va-ma-khoa-phuc-vu-ket-noi-du-lieu-bhyt-119260630165800133.htm', '2026-08-01', 1, '2026-10-02 15:42:31', '2026-10-02 15:42:31'),
(80, '10', 'Các trường hợp khác', NULL, NULL, NULL, 'https://xaydungchinhsach.chinhphu.vn/quy-dinh-danh-muc-ma-kham-chua-benh-va-ma-khoa-phuc-vu-ket-noi-du-lieu-bhyt-119260630165800133.htm', '2026-08-01', 1, '2026-10-02 15:42:31', '2026-10-02 15:42:31'),
(81, '11', 'Khám bệnh, chữa bệnh lưu động', NULL, NULL, 'Áp dụng khi cung cấp dịch vụ ngoài địa điểm ghi trong giấy phép hoạt động, không gồm KCB tại nhà mã 12', 'https://xaydungchinhsach.chinhphu.vn/quy-dinh-danh-muc-ma-kham-chua-benh-va-ma-khoa-phuc-vu-ket-noi-du-lieu-bhyt-119260630165800133.htm', '2026-08-01', 1, '2026-10-02 15:42:31', '2026-10-02 15:42:31'),
(82, '12', 'Khám bệnh, chữa bệnh tại nhà', NULL, NULL, NULL, 'https://xaydungchinhsach.chinhphu.vn/quy-dinh-danh-muc-ma-kham-chua-benh-va-ma-khoa-phuc-vu-ket-noi-du-lieu-bhyt-119260630165800133.htm', '2026-08-01', 1, '2026-10-02 15:42:31', '2026-10-02 15:42:31'),
(83, '13', 'Khám bệnh, chữa bệnh y học gia đình', NULL, NULL, 'Áp dụng tại cơ sở KCB y học gia đình hoặc cơ sở có phạm vi chuyên môn y học gia đình', 'https://xaydungchinhsach.chinhphu.vn/quy-dinh-danh-muc-ma-kham-chua-benh-va-ma-khoa-phuc-vu-ket-noi-du-lieu-bhyt-119260630165800133.htm', '2026-08-01', 1, '2026-10-02 15:42:31', '2026-10-02 15:42:31'),
(84, '14', 'Khám bệnh, chữa bệnh từ xa', NULL, NULL, NULL, 'https://xaydungchinhsach.chinhphu.vn/quy-dinh-danh-muc-ma-kham-chua-benh-va-ma-khoa-phuc-vu-ket-noi-du-lieu-bhyt-119260630165800133.htm', '2026-08-01', 1, '2026-10-02 15:42:31', '2026-10-02 15:42:31'),
(85, '15', 'Khám sức khoẻ định kỳ', NULL, NULL, 'BHYT chỉ áp dụng khi có quy định của cấp có thẩm quyền về thanh toán từ Quỹ BHYT', 'https://xaydungchinhsach.chinhphu.vn/quy-dinh-danh-muc-ma-kham-chua-benh-va-ma-khoa-phuc-vu-ket-noi-du-lieu-bhyt-119260630165800133.htm', '2026-08-01', 1, '2026-10-02 15:42:31', '2026-10-02 15:42:31'),
(86, '16', 'Khám sàng lọc', NULL, NULL, 'BHYT chỉ áp dụng khi có quy định của cấp có thẩm quyền về thanh toán từ Quỹ BHYT', 'https://xaydungchinhsach.chinhphu.vn/quy-dinh-danh-muc-ma-kham-chua-benh-va-ma-khoa-phuc-vu-ket-noi-du-lieu-bhyt-119260630165800133.htm', '2026-08-01', 1, '2026-10-02 15:42:31', '2026-10-02 15:42:31');
INSERT INTO `doituong_kcb_backup_3276` (`id`, `ma`, `truong_hop`, `quy_dinh`, `muc_huong`, `ghi_chu`, `nguon`, `ngay_hieu_luc`, `is_active`, `created_at`, `updated_at`) VALUES
(1, '1.1', 'Đến KCB đúng cơ sở KCB nơi đăng ký KCB BHYT ban đầu (Trừ trường hợp quy định tại mã 1.2)', NULL, '100% chi phí KCB theo phạm vi quyền lợi, mức hưởng', NULL, 'https://thuvienphapluat.vn/chinh-sach-phap-luat-moi/vn/ho-tro-phap-luat/chinh-sach-moi/96899/danh-muc-ma-doi-tuong-den-kham-chua-benh-tu-ngay-17-10-2025-quyet-dinh-3276-qd-byt', '2025-10-17', 1, '2026-10-02 14:54:09', '2026-10-02 14:54:09'),
(2, '1.2', 'Đi KCB tại cơ sở KCB cấp ban đầu bao gồm trạm y tế, cơ sở KCB y học gia đình, trạm y tế quân - dân y, trung tâm y tế huyện (trung tâm y tế khu vực từ 01/7/2025) được cấp giấy phép hoạt động theo hình thức tổ chức là phòng khám, y tế cơ quan, đơn vị, tổ chức được tổ chức dưới hình thức trạm y tế hoặc phòng khám, cơ sở KCB cấp ban đầu trong quân đội, công an (Bao gồm cả trường hợp đến đúng cơ sở KCB nơi đăng ký KCB BHYT ban đầu và đi KCB không đúng nơi đăng ký KCB BHYT ban đầu)', '- Điểm c khoản 1 Điều 22 Luật Bảo hiểm y tế - Điểm c khoản 4 Điều 22 Luật Bảo hiểm y tế - Điều 3 Thông tư 01/2025/TT-BYT', '100% chi phí KCB theo phạm vi quyền lợi (không phụ thuộc mức hưởng trên thẻ BHYT)', NULL, 'https://thuvienphapluat.vn/chinh-sach-phap-luat-moi/vn/ho-tro-phap-luat/chinh-sach-moi/96899/danh-muc-ma-doi-tuong-den-kham-chua-benh-tu-ngay-17-10-2025-quyet-dinh-3276-qd-byt', '2025-10-17', 1, '2026-10-02 14:54:09', '2026-10-02 14:54:09'),
(3, '1.3', 'Đến KCB có phiếu chuyển cơ sở KCB (Bao gồm Phiếu chuyển cơ sở KCB có giá trị 1 năm)', 'Điều 9, Điều 10 Thông tư 01/2025/TT-BYT', '100% chi phí KCB theo phạm vi quyền lợi, mức hưởng', NULL, 'https://thuvienphapluat.vn/chinh-sach-phap-luat-moi/vn/ho-tro-phap-luat/chinh-sach-moi/96899/danh-muc-ma-doi-tuong-den-kham-chua-benh-tu-ngay-17-10-2025-quyet-dinh-3276-qd-byt', '2025-10-17', 1, '2026-10-02 14:54:09', '2026-10-02 14:54:09'),
(4, '1.4', 'Trường hợp KCB khi thay đổi nơi lưu trú, nơi cư trú theo quy định tại Điều 4 Thông tư số 01/2025/TT- BYT', '- Khoản 3 Điều 22 Luật Bảo hiểm y tế - Điều 4 Thông tư 01/2025/TT-BYT', '100% chi phí KCB theo phạm vi quyền lợi, mức hưởng', NULL, 'https://thuvienphapluat.vn/chinh-sach-phap-luat-moi/vn/ho-tro-phap-luat/chinh-sach-moi/96899/danh-muc-ma-doi-tuong-den-kham-chua-benh-tu-ngay-17-10-2025-quyet-dinh-3276-qd-byt', '2025-10-17', 1, '2026-10-02 14:54:09', '2026-10-02 14:54:09'),
(5, '1.5', 'Đến KCB theo phiếu hẹn khám lại theo quy định tại Điều 11 Thông tư số 01/2025/TT-BYT', 'Điều 11 Thông tư 01/2025/TT-BYT', '100% chi phí KCB theo phạm vi quyền lợi, mức hưởng', NULL, 'https://thuvienphapluat.vn/chinh-sach-phap-luat-moi/vn/ho-tro-phap-luat/chinh-sach-moi/96899/danh-muc-ma-doi-tuong-den-kham-chua-benh-tu-ngay-17-10-2025-quyet-dinh-3276-qd-byt', '2025-10-17', 1, '2026-10-02 14:54:09', '2026-10-02 14:54:09'),
(6, '1.6', 'Người đã hiến bộ phận cơ thể của mình phải điều trị ngay sau khi hiến bộ phận cơ thể', 'Khoản 4 Điều 37 Nghị định 188/2025/NĐ-CP', '100% chi phí KCB theo phạm vi quyền lợi, mức hưởng', NULL, 'https://thuvienphapluat.vn/chinh-sach-phap-luat-moi/vn/ho-tro-phap-luat/chinh-sach-moi/96899/danh-muc-ma-doi-tuong-den-kham-chua-benh-tu-ngay-17-10-2025-quyet-dinh-3276-qd-byt', '2025-10-17', 1, '2026-10-02 14:54:09', '2026-10-02 14:54:09'),
(7, '1.7', 'Trẻ sơ sinh phải điều trị ngay sau khi sinh ra', 'Khoản 2 Điều 37 Nghị định 188/2025/NĐ-CP', '100% chi phí KCB theo phạm vi quyền lợi, mức hưởng', NULL, 'https://thuvienphapluat.vn/chinh-sach-phap-luat-moi/vn/ho-tro-phap-luat/chinh-sach-moi/96899/danh-muc-ma-doi-tuong-den-kham-chua-benh-tu-ngay-17-10-2025-quyet-dinh-3276-qd-byt', '2025-10-17', 1, '2026-10-02 14:54:09', '2026-10-02 14:54:09'),
(8, '1.11', 'Tự đến KCB tại cơ sở KCB cấp ban đầu còn lại không thuộc mã 1.2', 'Điểm c khoản 4 Điều 22 Luật Bảo hiểm y tế', '100% chi phí KCB theo phạm vi quyền lợi, mức hưởng', NULL, 'https://thuvienphapluat.vn/chinh-sach-phap-luat-moi/vn/ho-tro-phap-luat/chinh-sach-moi/96899/danh-muc-ma-doi-tuong-den-kham-chua-benh-tu-ngay-17-10-2025-quyet-dinh-3276-qd-byt', '2025-10-17', 1, '2026-10-02 14:54:09', '2026-10-02 14:54:09'),
(9, '1.12', 'Tự đến KCB ngoại trú tại cơ sở KCB cấp cơ bản đạt số điểm dưới 50 điểm hoặc được tạm xếp cấp cơ bản (trừ trường hợp KCB tại cơ sở KCB cấp cơ bản mà trước ngày 01/01/2025 đã được xác định là tuyến tỉnh hoặc tuyến trung ương)', 'Khoản 1 Điều 19 Nghị định 188/2025/NĐ-CP', '100% chi phí KCB theo phạm vi quyền lợi, mức hưởng', NULL, 'https://thuvienphapluat.vn/chinh-sach-phap-luat-moi/vn/ho-tro-phap-luat/chinh-sach-moi/96899/danh-muc-ma-doi-tuong-den-kham-chua-benh-tu-ngay-17-10-2025-quyet-dinh-3276-qd-byt', '2025-10-17', 1, '2026-10-02 14:54:09', '2026-10-02 14:54:09'),
(10, '1.13', 'Tự đến KCB ngoại trú tại cơ sở KCB cấp cơ bản đạt số điểm từ 50 - 70 điểm (trừ trường hợp các bệnh thuộc Phụ lục II ban hành kèm theo Thông tư số 01/2025/TT-BYT)', 'Khoản 2 Điều 19 Nghị định 188/2025/NĐ-CP', '- Từ ngày 01/01/2025 - 30/6/2026: Không được hưởng BHYT - Từ ngày 01/7/2026: 50% chi phí KCB theo phạm vi quyền lợi, mức hưởng', NULL, 'https://thuvienphapluat.vn/chinh-sach-phap-luat-moi/vn/ho-tro-phap-luat/chinh-sach-moi/96899/danh-muc-ma-doi-tuong-den-kham-chua-benh-tu-ngay-17-10-2025-quyet-dinh-3276-qd-byt', '2025-10-17', 1, '2026-10-02 14:54:09', '2026-10-02 14:54:09'),
(11, '1.14', 'Tự đến KCB ngoại trú tại cơ sở KCB cấp cơ bản mà trước ngày 01/01/2025 đã được xác định là tuyến tỉnh hoặc tuyến trung ương hoặc tương đương tuyến tỉnh hoặc tuyến trung ương (trừ trường hợp các bệnh thuộc Phụ lục II ban hành kèm theo Thông tư số 01/2025/TT-BYT)', 'Khoản 3 Điều 19 Nghị định 188/2025/NĐ-CP', '- Từ ngày 01/01/2025 - 30/6/2026: Không được hưởng BHYT - Từ ngày 01/7/2026: 50% chi phí KCB theo phạm vi quyền lợi, mức hưởng', NULL, 'https://thuvienphapluat.vn/chinh-sach-phap-luat-moi/vn/ho-tro-phap-luat/chinh-sach-moi/96899/danh-muc-ma-doi-tuong-den-kham-chua-benh-tu-ngay-17-10-2025-quyet-dinh-3276-qd-byt', '2025-10-17', 1, '2026-10-02 14:54:09', '2026-10-02 14:54:09'),
(12, '1.15', 'Tự đến KCB nội trú tại cơ sở KCB cấp cơ bản', 'Điểm d khoản 4 Điều 22 Luật Bảo hiểm y tế', '100% chi phí KCB theo phạm vi quyền lợi, mức hưởng', NULL, 'https://thuvienphapluat.vn/chinh-sach-phap-luat-moi/vn/ho-tro-phap-luat/chinh-sach-moi/96899/danh-muc-ma-doi-tuong-den-kham-chua-benh-tu-ngay-17-10-2025-quyet-dinh-3276-qd-byt', '2025-10-17', 1, '2026-10-02 14:54:09', '2026-10-02 14:54:09'),
