INSERT INTO `icd10` (`code`, `display_vi`, `display_en`, `definition_en`, `level`, `parent_code`, `chapter_id`, `chapter_code`, `section_id`, `type_code`, `is_leaf`, `is_active`, `coding_guidance`, `coding_guidance_en`, `properties_json`, `version`, `source`) VALUES
('D45', 'Đa hồng cầu', 'Polycythaemia vera', 'Polycythaemia vera', 'type', NULL, 'C00-D48', 'II', 'D37-D48', NULL, 1, 1, 'Lưu ý: Bệnh đa hồng cầu đã được phân loại lại trong ICD-O Phiên bản thứ ba với mã ác tính. Mã D45 sẽ tiếp tục được sử dụng, mặc dù mã này nằm trong chương dành cho u tân sinh về biểu hiện không chắc chắn hoặc không rõ ràng. Việc sửa đổi phân loại D45', 'Note: Polycythaemia vera has been reclassified in ICD-O Third Edition with a malignant code. The code D45 will continue to be used, although it is located in the chapter for Neoplasms of uncertain or unknown behaviour. The modification of its classification is reserved to the revision of ICD.', '{\"level\":\"type\",\"chapter-id\":\"C00-D48\",\"chapter-code\":\"II\",\"section-id\":\"D37-D48\",\"leaf\":true,\"coding-guidance\":\"Lưu ý: Bệnh đa hồng cầu đã được phân loại lại trong ICD-O Phiên bản thứ ba với mã ác tính. Mã D45 sẽ tiếp tục được sử dụng, mặc dù mã này nằm trong chương dành cho u tân sinh về biểu hiện không chắc chắn hoặc không rõ ràng. Việc sửa đổi phân loại D45\",\"coding-guidance-en\":\"Note: Polycythaemia vera has been reclassified in ICD-O Third Edition with a malignant code. The code D45 will continue to be used, although it is located in the chapter for Neoplasms of uncertain or unknown behaviour. The modification of its classification is reserved to the revision of ICD.\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('D46', 'Hội chứng loạn sản tuỷ xương', 'Myelodysplastic syndromes', 'Myelodysplastic syndromes', 'type', NULL, 'C00-D48', 'II', 'D37-D48', NULL, 0, 1, 'đ- ưBaợoc gdồàmnh: Hriộêin g chứng rối loạn sản tuỷ liên quan đến tác nhân alkyl - Hội chứng rối loạn sản tuỷ liên quan đến epipodophyllotoxin - Hội chứng rối loạn sản tuỷ liên quan đến quá trình điều trị không xác định khác - Loại trừ: thiếu máu bất sản do', 'Incl.: Alkylating-agent- related myelodysplastic syndrome Epipodophyllotoxin- related myelodysplastic syndrome Therapy-related myelodysplastic syndrome NOS Excl.: drug induced aplastic anaemia (D61.1)', '{\"level\":\"type\",\"chapter-id\":\"C00-D48\",\"chapter-code\":\"II\",\"section-id\":\"D37-D48\",\"leaf\":false,\"child-count\":9,\"superseded-by-more-specific\":true,\"coding-guidance\":\"đ- ưBaợoc gdồàmnh: Hriộêin g chứng rối loạn sản tuỷ liên quan đến tác nhân alkyl - Hội chứng rối loạn sản tuỷ liên quan đến epipodophyllotoxin - Hội chứng rối loạn sản tuỷ liên quan đến quá trình điều trị không xác định khác - Loại trừ: thiếu máu bất sản do\",\"coding-guidance-en\":\"Incl.: Alkylating-agent- related myelodysplastic syndrome Epipodophyllotoxin- related myelodysplastic syndrome Therapy-related myelodysplastic syndrome NOS Excl.: drug induced aplastic anaemia (D61.1)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('D46.0', 'Thiếu máu dai dẳng không có nguyên hồng cầu sắt vòng, đã được khẳng định', 'Refractory anaemia without ring sideroblasts, so stated', 'Refractory anaemia without ring sideroblasts, so stated', 'disease', 'D46', 'C00-D48', 'II', 'D37-D48', 'D46', 1, 1, 'tLhưuuố ýc :(D61.1) không có nguyên hồng cầu sắt, không tăng tế bào', 'Note: without sideroblasts, without excess of blasts', '{\"level\":\"disease\",\"chapter-id\":\"C00-D48\",\"chapter-code\":\"II\",\"section-id\":\"D37-D48\",\"type-code\":\"D46\",\"leaf\":true,\"coding-guidance\":\"tLhưuuố ýc :(D61.1) không có nguyên hồng cầu sắt, không tăng tế bào\",\"coding-guidance-en\":\"Note: without sideroblasts, without excess of blasts\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
