('D57.8', 'Rối loạn hồng cầu hình liềm khác', 'Other sickle-cell disorders', 'Other sickle-cell disorders', 'disease', 'D57', 'D50-D89', 'III', 'D55-D59', 'D57', 1, 1, NULL, NULL, '{\"level\":\"disease\",\"chapter-id\":\"D50-D89\",\"chapter-code\":\"III\",\"section-id\":\"D55-D59\",\"type-code\":\"D57\",\"leaf\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('D58', 'Thiếu máu tan máu di truyền khác', 'Other hereditary haemolytic anaemias', 'Other hereditary haemolytic anaemias', 'type', NULL, 'D50-D89', 'III', 'D55-D59', NULL, 0, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"D50-D89\",\"chapter-code\":\"III\",\"section-id\":\"D55-D59\",\"leaf\":false,\"child-count\":5,\"superseded-by-more-specific\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('D58.0', 'Hồng cầu hình cầu di truyền', 'Hereditary spherocytosis', 'Hereditary spherocytosis', 'disease', 'D58', 'D50-D89', 'III', 'D55-D59', 'D58', 1, 1, '- Vàng da không có sắc tố mật (di truyền) - Vàng da tan máu bẩm sinh (hồng cầu hình cầu) - Hội chứng', 'Acholuric (familial) jaundice Congenital (spherocytic) haemolytic icterus Minkowski-Chauffard syndrome', '{\"level\":\"disease\",\"chapter-id\":\"D50-D89\",\"chapter-code\":\"III\",\"section-id\":\"D55-D59\",\"type-code\":\"D58\",\"leaf\":true,\"coding-guidance\":\"- Vàng da không có sắc tố mật (di truyền) - Vàng da tan máu bẩm sinh (hồng cầu hình cầu) - Hội chứng\",\"coding-guidance-en\":\"Acholuric (familial) jaundice Congenital (spherocytic) haemolytic icterus Minkowski-Chauffard syndrome\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('D58.1', 'Hồng cầu hình bầu dục [oval] di truyền', 'Hereditary elliptocytosis', 'Hereditary elliptocytosis', 'disease', 'D58', 'D50-D89', 'III', 'D55-D59', 'D58', 1, 1, 'M- Biệnnkho whồsknig- cầu hình bầu dục (bẩm sinh) - Bệnh hồng cầu hình oval (bẩm', 'Elliptocytosis (congenital) Ovalocytosis (congenital)(hereditary)', '{\"level\":\"disease\",\"chapter-id\":\"D50-D89\",\"chapter-code\":\"III\",\"section-id\":\"D55-D59\",\"type-code\":\"D58\",\"leaf\":true,\"coding-guidance\":\"M- Biệnnkho whồsknig- cầu hình bầu dục (bẩm sinh) - Bệnh hồng cầu hình oval (bẩm\",\"coding-guidance-en\":\"Elliptocytosis (congenital) Ovalocytosis (congenital)(hereditary)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('D58.2', 'Bệnh lý huyết sắc tố khác', 'Other haemoglobinopathi es', 'Other haemoglobinopathi es', 'disease', 'D58', 'D50-D89', 'III', 'D55-D59', 'D58', 1, 1, '- Bệnh huyết sắc tố bất thường không xác định khác - Thiếu máu thể Heinz bẩm sinh - Bệnh: + Bệnh Hb-C + Bệnh Hb-D + Bệnh Hb-E + Bệnh rối loạn máu không xác định khác + Bệnh tan máu huyết sắc tố không ổn định - Loại trừ: + bệnh tăng hồng cầu di truyền (D75.0) + bệnh Hb-M (D74.0) + tồn tại di truyền của huyết sắc tố thai nhi [HPFH] (D56.4) + bệnh tăng hồng cầu ở những người sống ở', 'Abnormal haemoglobin NOS Congenital Heinz body anaemia Disease: Hb-C Hb-D Hb-E Haemoglobinopathy NOS Unstable haemoglobin haemolytic disease Excl.: familial polycythaemia (D75.0) Hb-M disease (D74.0) hereditary persistence of fetal haemoglobin [HPFH] (D56.4) high-altitude polycythaemia (D75.1) methaemoglobinaemia (D74.-)', '{\"level\":\"disease\",\"chapter-id\":\"D50-D89\",\"chapter-code\":\"III\",\"section-id\":\"D55-D59\",\"type-code\":\"D58\",\"leaf\":true,\"coding-guidance\":\"- Bệnh huyết sắc tố bất thường không xác định khác - Thiếu máu thể Heinz bẩm sinh - Bệnh: + Bệnh Hb-C + Bệnh Hb-D + Bệnh Hb-E + Bệnh rối loạn máu không xác định khác + Bệnh tan máu huyết sắc tố không ổn định - Loại trừ: + bệnh tăng hồng cầu di truyền (D75.0) + bệnh Hb-M (D74.0) + tồn tại di truyền của huyết sắc tố thai nhi [HPFH] (D56.4) + bệnh tăng hồng cầu ở những người sống ở\",\"coding-guidance-en\":\"Abnormal haemoglobin NOS Congenital Heinz body anaemia Disease: Hb-C Hb-D Hb-E Haemoglobinopathy NOS Unstable haemoglobin haemolytic disease Excl.: familial polycythaemia (D75.0) Hb-M disease (D74.0) hereditary persistence of fetal haemoglobin [HPFH] (D56.4) high-altitude polycythaemia (D75.1) methaemoglobinaemia (D74.-)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
