('E34', 'Rối loạn nội tiết khác', 'Other endocrine disorders', 'Other endocrine disorders', 'type', NULL, 'E00-E90', 'IV', 'E20-E35', NULL, 0, 1, 'Loại trừ: giả suy cận giáp (E20.1)', 'Excl.: pseudohypoparathyroi dism (E20.1)', '{\"level\":\"type\",\"chapter-id\":\"E00-E90\",\"chapter-code\":\"IV\",\"section-id\":\"E20-E35\",\"leaf\":false,\"child-count\":8,\"superseded-by-more-specific\":true,\"coding-guidance\":\"Loại trừ: giả suy cận giáp (E20.1)\",\"coding-guidance-en\":\"Excl.: pseudohypoparathyroi dism (E20.1)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('E34.0', 'Hội chứng carcinoid', 'Carcinoid syndrome', 'Carcinoid syndrome', 'disease', 'E34', 'E00-E90', 'IV', 'E20-E35', 'E34', 1, 1, 'Lưu ý: Nếu muốn, có thể được sử dụng như một mã bổ sung để xác định hoạt động chức năng liên quan đến khối', 'Note: May be used as an additional code, if desired, to identify functional activity associated with a carcinoid tumour.', '{\"level\":\"disease\",\"chapter-id\":\"E00-E90\",\"chapter-code\":\"IV\",\"section-id\":\"E20-E35\",\"type-code\":\"E34\",\"leaf\":true,\"discouraged-primary-diagnosis\":true,\"coding-guidance\":\"Lưu ý: Nếu muốn, có thể được sử dụng như một mã bổ sung để xác định hoạt động chức năng liên quan đến khối\",\"coding-guidance-en\":\"Note: May be used as an additional code, if desired, to identify functional activity associated with a carcinoid tumour.\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('E34.1', 'Tăng tiết khác của nội tiết tố [hormon] ruột', 'Other hypersecretion of intestinal hormones', 'Other hypersecretion of intestinal hormones', 'disease', 'E34', 'E00-E90', 'IV', 'E20-E35', 'E34', 1, 1, 'u carcinoid.', NULL, '{\"level\":\"disease\",\"chapter-id\":\"E00-E90\",\"chapter-code\":\"IV\",\"section-id\":\"E20-E35\",\"type-code\":\"E34\",\"leaf\":true,\"coding-guidance\":\"u carcinoid.\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('E34.2', 'Tiết nội tiết tố [hormon] lạc chỗ, không phân loại mục khác', 'Ectopic hormone secretion, not elsewhere classified', 'Ectopic hormone secretion, not elsewhere classified', 'disease', 'E34', 'E00-E90', 'IV', 'E20-E35', 'E34', 1, 1, NULL, NULL, '{\"level\":\"disease\",\"chapter-id\":\"E00-E90\",\"chapter-code\":\"IV\",\"section-id\":\"E20-E35\",\"type-code\":\"E34\",\"leaf\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs');
INSERT INTO `icd10` (`code`, `display_vi`, `display_en`, `definition_en`, `level`, `parent_code`, `chapter_id`, `chapter_code`, `section_id`, `type_code`, `is_leaf`, `is_active`, `coding_guidance`, `coding_guidance_en`, `properties_json`, `version`, `source`) VALUES
('E34.3', 'Vóc dáng lùn, không phân loại mục khác', 'Short stature, not elsewhere classified', 'Short stature, not elsewhere classified', 'disease', 'E34', 'E00-E90', 'IV', 'E20-E35', 'E34', 1, 1, '- Vóc dáng lùn: + không xác định khác + thể tạng + thể Laron + tâm lý xã hội - Loại trừ: + lão hoá sớm (E34.8) + hội chứng Russell - Silver (Q87.1) + chi ngắn kèm suy giảm miễn dịch (D82.2) + vóc dáng lùn: ++ do bất sản sụn (Q77.4) ++ do giảm sản sụn (Q77.4) ++ do các hội chứng biến dạng xác định - mã cho hội chứng - xem Chỉ mục theo thứ tự chữ cái (ICD-10 quyển 3 của WHO). ++ do dinh dưỡng (E45)', 'Short stature: NOS constitutional Laron-type psychosocial Excl.: progeria (E34.8) Russell-Silver syndrome (Q87.1) short-limbed stature with immunodeficiency (D82.2) short stature: achondroplastic (Q77.4) hypochondroplastic (Q77.4) in specific dysmorphic syndromes - code to syndrome - see Alphabetical Index nutritional (E45) pituitary (E23.0) renal (N25.0)', '{\"level\":\"disease\",\"chapter-id\":\"E00-E90\",\"chapter-code\":\"IV\",\"section-id\":\"E20-E35\",\"type-code\":\"E34\",\"leaf\":true,\"coding-guidance\":\"- Vóc dáng lùn: + không xác định khác + thể tạng + thể Laron + tâm lý xã hội - Loại trừ: + lão hoá sớm (E34.8) + hội chứng Russell - Silver (Q87.1) + chi ngắn kèm suy giảm miễn dịch (D82.2) + vóc dáng lùn: ++ do bất sản sụn (Q77.4) ++ do giảm sản sụn (Q77.4) ++ do các hội chứng biến dạng xác định - mã cho hội chứng - xem Chỉ mục theo thứ tự chữ cái (ICD-10 quyển 3 của WHO). ++ do dinh dưỡng (E45)\",\"coding-guidance-en\":\"Short stature: NOS constitutional Laron-type psychosocial Excl.: progeria (E34.8) Russell-Silver syndrome (Q87.1) short-limbed stature with immunodeficiency (D82.2) short stature: achondroplastic (Q77.4) hypochondroplastic (Q77.4) in specific dysmorphic syndromes - code to syndrome - see Alphabetical Index nutritional (E45) pituitary (E23.0) renal (N25.0)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('E34.4', 'Thể tạng cao', 'Constitutional tall stature', 'Constitutional tall stature', 'disease', 'E34', 'E00-E90', 'IV', 'E20-E35', 'E34', 1, 1, 'Thể tạng khổng lồ', 'Constitutional gigantism', '{\"level\":\"disease\",\"chapter-id\":\"E00-E90\",\"chapter-code\":\"IV\",\"section-id\":\"E20-E35\",\"type-code\":\"E34\",\"leaf\":true,\"coding-guidance\":\"Thể tạng khổng lồ\",\"coding-guidance-en\":\"Constitutional gigantism\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('E34.5', 'Hội chứng kháng androgen', 'Androgen resistance syndrome', 'Androgen resistance syndrome', 'disease', 'E34', 'E00-E90', 'IV', 'E20-E35', 'E34', 1, 1, '- Lưỡng giới giả nam kháng androgen - Rối loạn thụ thể hormon ở ngoại biên - Hội chứng Reifenstein', 'Male pseudohermaphroditis m with androgen resistance Peripheral hormonal receptor disorder Reifenstein syndrome Testicular feminization', '{\"level\":\"disease\",\"chapter-id\":\"E00-E90\",\"chapter-code\":\"IV\",\"section-id\":\"E20-E35\",\"type-code\":\"E34\",\"leaf\":true,\"coding-guidance\":\"- Lưỡng giới giả nam kháng androgen - Rối loạn thụ thể hormon ở ngoại biên - Hội chứng Reifenstein\",\"coding-guidance-en\":\"Male pseudohermaphroditis m with androgen resistance Peripheral hormonal receptor disorder Reifenstein syndrome Testicular feminization\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('E34.8', 'Rối loạn nội tiết xác định khác', 'Other specified endocrine disorders', 'Other specified endocrine disorders', 'disease', 'E34', 'E00-E90', 'IV', 'E20-E35', 'E34', 1, 1, '-- TRiốnih l ohạonà nch nứữc năng tuyến tùng - Lão hoá sớm [Progeria]', '(Psiynnedarlo gmlaen)d dysfunction Progeria', '{\"level\":\"disease\",\"chapter-id\":\"E00-E90\",\"chapter-code\":\"IV\",\"section-id\":\"E20-E35\",\"type-code\":\"E34\",\"leaf\":true,\"coding-guidance\":\"-- TRiốnih l ohạonà nch nứữc năng tuyến tùng - Lão hoá sớm [Progeria]\",\"coding-guidance-en\":\"(Psiynnedarlo gmlaen)d dysfunction Progeria\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('E34.9', 'Rối loạn nội tiết, không xác định', 'Endocrine disorder, unspecified', 'Endocrine disorder, unspecified', 'disease', 'E34', 'E00-E90', 'IV', 'E20-E35', 'E34', 1, 1, '- Rối loạn: + nội tiết không xác định khác + hormon không xác định khác', 'Disturbance: endocrine NOS hormone NOS', '{\"level\":\"disease\",\"chapter-id\":\"E00-E90\",\"chapter-code\":\"IV\",\"section-id\":\"E20-E35\",\"type-code\":\"E34\",\"leaf\":true,\"coding-guidance\":\"- Rối loạn: + nội tiết không xác định khác + hormon không xác định khác\",\"coding-guidance-en\":\"Disturbance: endocrine NOS hormone NOS\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
