('F73.9', 'Chậm phát triển trí tuệ trầm trọng, không đề cập đến suy giảm hành vi', 'Profound mental retardation, without mention of impairment of behaviour', 'Profound mental retardation, without mention of impairment of behaviour', 'disease', 'F73', 'F00-F99', 'V', 'F70-F79', 'F73', 1, 1, NULL, NULL, '{\"level\":\"disease\",\"chapter-id\":\"F00-F99\",\"chapter-code\":\"V\",\"section-id\":\"F70-F79\",\"type-code\":\"F73\",\"leaf\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('F78', 'Chậm phát triển trí tuệ khác', 'Other mental retardation', 'Other mental retardation', 'type', NULL, 'F00-F99', 'V', 'F70-F79', NULL, 0, 1, '[Tham khảo Khối F70.- - F79.- Phụ lục 1A của Thông tư này để hiểu quy tắc xây dựng', '[See before F70 for subdivisions]', '{\"level\":\"type\",\"chapter-id\":\"F00-F99\",\"chapter-code\":\"V\",\"section-id\":\"F70-F79\",\"leaf\":false,\"child-count\":4,\"superseded-by-more-specific\":true,\"coding-guidance\":\"[Tham khảo Khối F70.- - F79.- Phụ lục 1A của Thông tư này để hiểu quy tắc xây dựng\",\"coding-guidance-en\":\"[See before F70 for subdivisions]\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
