INSERT INTO `icd10` (`code`, `display_vi`, `display_en`, `definition_en`, `level`, `parent_code`, `chapter_id`, `chapter_code`, `section_id`, `type_code`, `is_leaf`, `is_active`, `coding_guidance`, `coding_guidance_en`, `properties_json`, `version`, `source`) VALUES
('G43', 'Bệnh đau nửa đầu [migraine]', 'Migraine', 'Migraine', 'type', NULL, 'G00-G99', 'VI', 'G40-G47', NULL, 0, 1, 'Nếu muốn, có thể sử dụng bổ sung mã nguyên nhân bên ngoài (Chương XX) để xác định thuốc, nếu do thuốc gây ra. - Loại trừ: đau đầu', 'Use additional external cause code (Chapter XX), if desired, to identify drug, if drug-induced. Excl.: headache NOS (R51)', '{\"level\":\"type\",\"chapter-id\":\"G00-G99\",\"chapter-code\":\"VI\",\"section-id\":\"G40-G47\",\"leaf\":false,\"child-count\":6,\"superseded-by-more-specific\":true,\"coding-guidance\":\"Nếu muốn, có thể sử dụng bổ sung mã nguyên nhân bên ngoài (Chương XX) để xác định thuốc, nếu do thuốc gây ra. - Loại trừ: đau đầu\",\"coding-guidance-en\":\"Use additional external cause code (Chapter XX), if desired, to identify drug, if drug-induced. Excl.: headache NOS (R51)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('G43.0', 'Bệnh đau nửa đầu [migraine] không có tiền triệu [aura] [migraine thường]', 'Migraine without aura [common migraine]', 'Migraine without aura [common migraine]', 'disease', 'G43', 'G00-G99', 'VI', 'G40-G47', 'G43', 1, 1, 'không xác định', NULL, '{\"level\":\"disease\",\"chapter-id\":\"G00-G99\",\"chapter-code\":\"VI\",\"section-id\":\"G40-G47\",\"type-code\":\"G43\",\"leaf\":true,\"coding-guidance\":\"không xác định\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('G43.1', 'Bệnh đau nửa đầu [Migraine] có tiền triệu [aura] [Migraine cổ điển]', 'Migraine with aura [classical migraine]', 'Migraine with aura [classical migraine]', 'disease', 'G43', 'G00-G99', 'VI', 'G40-G47', 'G43', 1, 1, '- Bệnh đau nửa đầu [migraine]: + tiền triệu không có nhức đầu + nền + cơn tương đương + liệt nửa người di truyền + kèm: ++ tiền triệu khởi phát cấp tính ++ tiền triệu kéo dài', 'Migraine: aura without headache basilar equivalents familial hemiplegic with: acute- onset aura prolonged aura typical aura', '{\"level\":\"disease\",\"chapter-id\":\"G00-G99\",\"chapter-code\":\"VI\",\"section-id\":\"G40-G47\",\"type-code\":\"G43\",\"leaf\":true,\"coding-guidance\":\"- Bệnh đau nửa đầu [migraine]: + tiền triệu không có nhức đầu + nền + cơn tương đương + liệt nửa người di truyền + kèm: ++ tiền triệu khởi phát cấp tính ++ tiền triệu kéo dài\",\"coding-guidance-en\":\"Migraine: aura without headache basilar equivalents familial hemiplegic with: acute- onset aura prolonged aura typical aura\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('G43.2', 'Tình trạng đau nửa đầu [migraine] dai dẳng', 'Status migrainosus', 'Status migrainosus', 'disease', 'G43', 'G00-G99', 'VI', 'G40-G47', 'G43', 1, 1, '++ tiền triệu điển', NULL, '{\"level\":\"disease\",\"chapter-id\":\"G00-G99\",\"chapter-code\":\"VI\",\"section-id\":\"G40-G47\",\"type-code\":\"G43\",\"leaf\":true,\"coding-guidance\":\"++ tiền triệu điển\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
