('O90.9', 'Biến chứng trong thời kỳ sau đẻ, không xác định', 'Complication of the puerperium, unspecified', 'Complication of the puerperium, unspecified', 'disease', 'O90', 'O00-O99', 'XV', 'O85-O92', 'O90', 1, 1, NULL, NULL, '{\"level\":\"disease\",\"chapter-id\":\"O00-O99\",\"chapter-code\":\"XV\",\"section-id\":\"O85-O92\",\"type-code\":\"O90\",\"leaf\":true,\"female-only\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('O91', 'Nhiễm trùng vú liên quan đến sinh đẻ', 'Infections of breast associated with childbirth', 'Infections of breast associated with childbirth', 'type', NULL, 'O00-O99', 'XV', 'O85-O92', NULL, 0, 1, 'Bao gồm: bệnh lý được liệt kê trong thai kỳ, sau đẻ hoặc trong thời gian cho con bú', 'Incl.: the listed conditions during pregnancy, the puerperium or lactation', '{\"level\":\"type\",\"chapter-id\":\"O00-O99\",\"chapter-code\":\"XV\",\"section-id\":\"O85-O92\",\"leaf\":false,\"child-count\":3,\"superseded-by-more-specific\":true,\"female-only\":true,\"coding-guidance\":\"Bao gồm: bệnh lý được liệt kê trong thai kỳ, sau đẻ hoặc trong thời gian cho con bú\",\"coding-guidance-en\":\"Incl.: the listed conditions during pregnancy, the puerperium or lactation\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('O91.0', 'Nhiễm trùng núm vú liên quan đến sinh đẻ', 'Infection of nipple associated with childbirth', 'Infection of nipple associated with childbirth', 'disease', 'O91', 'O00-O99', 'XV', 'O85-O92', 'O91', 1, 1, '- Áp xe núm vú: + khi có thai + sau đẻ', 'Abscess of nipple: gestational puerperal', '{\"level\":\"disease\",\"chapter-id\":\"O00-O99\",\"chapter-code\":\"XV\",\"section-id\":\"O85-O92\",\"type-code\":\"O91\",\"leaf\":true,\"female-only\":true,\"coding-guidance\":\"- Áp xe núm vú: + khi có thai + sau đẻ\",\"coding-guidance-en\":\"Abscess of nipple: gestational puerperal\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('O91.1', 'Áp xe vú liên quan đến sinh đẻ', 'Abscess of breast associated with childbirth', 'Abscess of breast associated with childbirth', 'disease', 'O91', 'O00-O99', 'XV', 'O85-O92', 'O91', 1, 1, '- Áp xe tuyến vú trong thai kỳ hoặc sau đẻ - Viêm vú có mủ trong thai kỳ hoặc sau đẻ - Áp xe dưới quầng vú trong thai kỳ hoặc sau đẻ', 'Mammary abscess gestational or puerperal Purulent mastitis gestational or puerperal Subareolar abscess gestational or puerperal', '{\"level\":\"disease\",\"chapter-id\":\"O00-O99\",\"chapter-code\":\"XV\",\"section-id\":\"O85-O92\",\"type-code\":\"O91\",\"leaf\":true,\"female-only\":true,\"coding-guidance\":\"- Áp xe tuyến vú trong thai kỳ hoặc sau đẻ - Viêm vú có mủ trong thai kỳ hoặc sau đẻ - Áp xe dưới quầng vú trong thai kỳ hoặc sau đẻ\",\"coding-guidance-en\":\"Mammary abscess gestational or puerperal Purulent mastitis gestational or puerperal Subareolar abscess gestational or puerperal\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('O91.2', 'Viêm vú không thành mủ liên quan đến sinh đẻ', 'Nonpurulent mastitis associated with childbirth', 'Nonpurulent mastitis associated with childbirth', 'disease', 'O91', 'O00-O99', 'XV', 'O85-O92', 'O91', 1, 1, '- Viêm hạch ở vú trong thai kỳ hoặc sau đẻ - Viêm vú: + trong thai kỳ hoặc sau đẻ không xác định khác + trong thai kỳ hoặc sau đẻ + nhu mô trong thai kỳ hoặc sau đẻ', 'Lymphangitis of breast gestational or puerperal Mastitis: NOS gestational or puerperal interstitial gestational or puerperal parenchymatous gestational or', '{\"level\":\"disease\",\"chapter-id\":\"O00-O99\",\"chapter-code\":\"XV\",\"section-id\":\"O85-O92\",\"type-code\":\"O91\",\"leaf\":true,\"female-only\":true,\"coding-guidance\":\"- Viêm hạch ở vú trong thai kỳ hoặc sau đẻ - Viêm vú: + trong thai kỳ hoặc sau đẻ không xác định khác + trong thai kỳ hoặc sau đẻ + nhu mô trong thai kỳ hoặc sau đẻ\",\"coding-guidance-en\":\"Lymphangitis of breast gestational or puerperal Mastitis: NOS gestational or puerperal interstitial gestational or puerperal parenchymatous gestational or\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('O92', 'Rối loạn khác của vú và/hoặc tiết sữa liên quan đến sinh đẻ', 'Other disorders of breast and lactation associated with childbirth', 'Other disorders of breast and lactation associated with childbirth', 'type', NULL, 'O00-O99', 'XV', 'O85-O92', NULL, 0, 1, 'Bao gồm: bệnh lý được liệt kê trong thai kỳ, sau đẻ hoặc trong thời gian cho con bú', 'pInucel.r:p tehrea llisted conditions during pregnancy, the puerperium or lactation', '{\"level\":\"type\",\"chapter-id\":\"O00-O99\",\"chapter-code\":\"XV\",\"section-id\":\"O85-O92\",\"leaf\":false,\"child-count\":8,\"superseded-by-more-specific\":true,\"female-only\":true,\"coding-guidance\":\"Bao gồm: bệnh lý được liệt kê trong thai kỳ, sau đẻ hoặc trong thời gian cho con bú\",\"coding-guidance-en\":\"pInucel.r:p tehrea llisted conditions during pregnancy, the puerperium or lactation\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
