('R61.9', 'Tăng tiết mồ hôi, không xác định', 'Hyperhidrosis, unspecified', 'Hyperhidrosis, unspecified', 'disease', 'R61', 'R00-R99', 'XVIII', 'R50-R69', 'R61', 1, 1, '- Tiết mồ hôi quá mức - Tiết mồ hôi ban đêm', 'Excessive sweating Night sweats', '{\"level\":\"disease\",\"chapter-id\":\"R00-R99\",\"chapter-code\":\"XVIII\",\"section-id\":\"R50-R69\",\"type-code\":\"R61\",\"leaf\":true,\"coding-guidance\":\"- Tiết mồ hôi quá mức - Tiết mồ hôi ban đêm\",\"coding-guidance-en\":\"Excessive sweating Night sweats\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('R62', 'Phát triển sinh lý không bình thường như kỳ vọng', 'Lack of expected normal physiological development', 'Lack of expected normal physiological development', 'type', NULL, 'R00-R99', 'XVIII', 'R50-R69', NULL, 0, 1, 'Loại trừ: dậy thì muộn (E30.0)', 'Excl.: delayed puberty (E30.0)', '{\"level\":\"type\",\"chapter-id\":\"R00-R99\",\"chapter-code\":\"XVIII\",\"section-id\":\"R50-R69\",\"leaf\":false,\"child-count\":3,\"superseded-by-more-specific\":true,\"coding-guidance\":\"Loại trừ: dậy thì muộn (E30.0)\",\"coding-guidance-en\":\"Excl.: delayed puberty (E30.0)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('R62.0', 'Chậm đạt các mốc phát triển', 'Delayed milestone', 'Delayed milestone', 'disease', 'R62', 'R00-R99', 'XVIII', 'R50-R69', 'R62', 1, 1, '- Chậm đạt được giai đoạn phát triển sinh lý như kỳ vọng - Chậm: + nói', 'Delayed attainment of expected physiological developmental stage Late: talker walker', '{\"level\":\"disease\",\"chapter-id\":\"R00-R99\",\"chapter-code\":\"XVIII\",\"section-id\":\"R50-R69\",\"type-code\":\"R62\",\"leaf\":true,\"coding-guidance\":\"- Chậm đạt được giai đoạn phát triển sinh lý như kỳ vọng - Chậm: + nói\",\"coding-guidance-en\":\"Delayed attainment of expected physiological developmental stage Late: talker walker\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('R62.8', 'Phát triển sinh lý không bình thường như kỳ vọng khác', 'Other lack of expected normal physiological development', 'Other lack of expected normal physiological development', 'disease', 'R62', 'R00-R99', 'XVIII', 'R50-R69', 'R62', 1, 1, '+- Kđéim: + tăng cân + phát triển (ở trẻ em) không xác định khác - Nhi tính [đã lớn tuổi mà vẫn không phát triển về cơ thể, trí óc và cơ quan sinh dục] không xác định khác - Không phát triển - Chậm phát triển thể chất - Loại trừ: suy nhược cơ thể ở người trưởng thành (R64) + bệnh HIV dẫn đến suy nhược cơ thể (B22.2) + chậm phát triển', 'Failure to: gain weight thrive (in child) NOS Infantilism NOS Lack of growth Physical retardation Excl.: failure to thrive in adult (R64) HIV disease resulting in failure to thrive (B22.2) physical retardation due to malnutrition (E45)', '{\"level\":\"disease\",\"chapter-id\":\"R00-R99\",\"chapter-code\":\"XVIII\",\"section-id\":\"R50-R69\",\"type-code\":\"R62\",\"leaf\":true,\"coding-guidance\":\"+- Kđéim: + tăng cân + phát triển (ở trẻ em) không xác định khác - Nhi tính [đã lớn tuổi mà vẫn không phát triển về cơ thể, trí óc và cơ quan sinh dục] không xác định khác - Không phát triển - Chậm phát triển thể chất - Loại trừ: suy nhược cơ thể ở người trưởng thành (R64) + bệnh HIV dẫn đến suy nhược cơ thể (B22.2) + chậm phát triển\",\"coding-guidance-en\":\"Failure to: gain weight thrive (in child) NOS Infantilism NOS Lack of growth Physical retardation Excl.: failure to thrive in adult (R64) HIV disease resulting in failure to thrive (B22.2) physical retardation due to malnutrition (E45)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('R62.9', 'Phát triển sinh lý không bình thường như kỳ vọng, không xác định', 'Lack of expected normal physiological development, unspecified', 'Lack of expected normal physiological development, unspecified', 'disease', 'R62', 'R00-R99', 'XVIII', 'R50-R69', 'R62', 1, 1, 'thể chất do suy', NULL, '{\"level\":\"disease\",\"chapter-id\":\"R00-R99\",\"chapter-code\":\"XVIII\",\"section-id\":\"R50-R69\",\"type-code\":\"R62\",\"leaf\":true,\"coding-guidance\":\"thể chất do suy\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('R63', 'Triệu chứng và/hoặc dấu hiệu liên quan đến ăn uống thức ăn và/hoặc đồ uống', 'Symptoms and signs concerning food and fluid intake', 'Symptoms and signs concerning food and fluid intake', 'type', NULL, 'R00-R99', 'XVIII', 'R50-R69', NULL, 0, 1, '- Loại trừ: chứng háu ăn không xác định khác (F50.2) + rối loạn ăn không có nguồn gốc thực thể (F50.-) + suy dinh dưỡng (E40-E46)', 'Excl.: bulimia NOS (F50.2) eating disorders of nonorganic origin (F50.-) malnutrition (E40-E46)', '{\"level\":\"type\",\"chapter-id\":\"R00-R99\",\"chapter-code\":\"XVIII\",\"section-id\":\"R50-R69\",\"leaf\":false,\"child-count\":8,\"superseded-by-more-specific\":true,\"coding-guidance\":\"- Loại trừ: chứng háu ăn không xác định khác (F50.2) + rối loạn ăn không có nguồn gốc thực thể (F50.-) + suy dinh dưỡng (E40-E46)\",\"coding-guidance-en\":\"Excl.: bulimia NOS (F50.2) eating disorders of nonorganic origin (F50.-) malnutrition (E40-E46)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs');
