('V97', 'Các tai nạn do phương tịên bay xác định khác', 'Other specified air transport accidents', 'Other specified air transport accidents', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 0, 1, 'Bao gồm: tai nạn gây ra cho những người không ở trên phương tiện bay', 'Incl.: accidents to nonoccupants of aircraft', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":false,\"child-count\":5,\"not-primary-diagnosis\":true,\"superseded-by-more-specific\":true,\"coding-guidance\":\"Bao gồm: tai nạn gây ra cho những người không ở trên phương tiện bay\",\"coding-guidance-en\":\"Incl.: accidents to nonoccupants of aircraft\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('V97.0', 'Người ở trên phương tiện bay bị thương trong tai nạn vận tải hàng không xác định khác', 'Occupant of aircraft injured in other specified air transport accidents', 'Occupant of aircraft injured in other specified air transport accidents', 'disease', 'V97', 'V01-Y98', 'XX', 'V01-X59', 'V97', 1, 1, '- Bị rơi vào, trên hoặc từ phương tiện bay trong tai nạn hàng không. - Loại trừ: tai nạn khi lên hoặc xuống phương tiện bay (V97.1)', 'Fall in, on or from aircraft in air transport accident Excl.: accident while boarding or alighting (V97.1)', '{\"level\":\"disease\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"type-code\":\"V97\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bị rơi vào, trên hoặc từ phương tiện bay trong tai nạn hàng không. - Loại trừ: tai nạn khi lên hoặc xuống phương tiện bay (V97.1)\",\"coding-guidance-en\":\"Fall in, on or from aircraft in air transport accident Excl.: accident while boarding or alighting (V97.1)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('V97.1', 'Người bị thương khi lên xuống máy bay', 'Person injured while boarding or alighting from aircraft', 'Person injured while boarding or alighting from aircraft', 'disease', 'V97', 'V01-Y98', 'XX', 'V01-X59', 'V97', 1, 1, NULL, NULL, '{\"level\":\"disease\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"type-code\":\"V97\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('V97.2', 'Người nhảy dù bị thương trong tai nạn vận tải hàng không', 'Parachutist injured in air transport accident', 'Parachutist injured in air transport accident', 'disease', 'V97', 'V01-Y98', 'XX', 'V01-X59', 'V97', 1, 1, 'Loại trừ: người nhảy xuống sau tai nạn phương tiện bay (V95-V96)', 'Excl.: person making descent after accident to aircraft (V95-V96)', '{\"level\":\"disease\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"type-code\":\"V97\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"Loại trừ: người nhảy xuống sau tai nạn phương tiện bay (V95-V96)\",\"coding-guidance-en\":\"Excl.: person making descent after accident to aircraft (V95-V96)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('V97.3', 'Người trên mặt đất bị thương trong tai nạn vận tải hàng không', 'Person on ground injured in air transport accident', 'Person on ground injured in air transport accident', 'disease', 'V97', 'V01-Y98', 'XX', 'V01-X59', 'V97', 1, 1, '- Bị va đập do vật rơi từ máy bay - Bị thương do cánh quạt quay - Bị hút, cuốn vào máy bay', 'Hit by object falling from aircraft Injured by rotating propeller Sucked into jet', '{\"level\":\"disease\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"type-code\":\"V97\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bị va đập do vật rơi từ máy bay - Bị thương do cánh quạt quay - Bị hút, cuốn vào máy bay\",\"coding-guidance-en\":\"Hit by object falling from aircraft Injured by rotating propeller Sucked into jet\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('V97.8', 'Các tai nạn vận tải hàng không khác, không phân loại mục khác', 'Other air transport accidents, not elsewhere classified', 'Other air transport accidents, not elsewhere classified', 'disease', 'V97', 'V01-Y98', 'XX', 'V01-X59', 'V97', 1, 1, '- Các thương tích gây ra do máy móc trên phương tiện bay - Loại trừ: tai nạn phương tiện bay không xác định khác (V95.9) + bị ảnh hưởng bởi áp lực không', 'Injury from machinery on aircraft Excl.: aircraft accident NOS (V95.9) exposure to changes in air pressure during ascent or descent (W94)', '{\"level\":\"disease\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"type-code\":\"V97\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Các thương tích gây ra do máy móc trên phương tiện bay - Loại trừ: tai nạn phương tiện bay không xác định khác (V95.9) + bị ảnh hưởng bởi áp lực không\",\"coding-guidance-en\":\"Injury from machinery on aircraft Excl.: aircraft accident NOS (V95.9) exposure to changes in air pressure during ascent or descent (W94)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('V98', 'Các tai nạn giao thông xác định khác', 'Other specified transport accidents', 'Other specified transport accidents', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, 'k- hBía koh gi ồlêmn: htaoiặ nc ạn, về hoặc liên quan đến: ++ cáp treo, không phải trên đường ray ++ du thuyền băng ++ du thuyền trên đất liền ++ xe cáp treo trượt tuyết ++ cáp treo trượt tuyết bằng thuyền gondola + bị kẹt hoặc kéo lê bởi cáp treo, không phải trên đường ray + ngã hoặc nhảy từ cáp treo, không phải trên đường rayy + vật được ném', 'Incl.: accident to, on or involving: cable-car, not on rails ice-yacht land- yacht ski chair- lift ski-lift with gondola caught or dragged by fall or jump from object thrown from or in', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"k- hBía koh gi ồlêmn: htaoiặ nc ạn, về hoặc liên quan đến: ++ cáp treo, không phải trên đường ray ++ du thuyền băng ++ du thuyền trên đất liền ++ xe cáp treo trượt tuyết ++ cáp treo trượt tuyết bằng thuyền gondola + bị kẹt hoặc kéo lê bởi cáp treo, không phải trên đường ray + ngã hoặc nhảy từ cáp treo, không phải trên đường rayy + vật được ném\",\"coding-guidance-en\":\"Incl.: accident to, on or involving: cable-car, not on rails ice-yacht land- yacht ski chair- lift ski-lift with gondola caught or dragged by fall or jump from object thrown from or in\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('V99', 'Tai nạn giao thông không xác định', 'Unspecified transport accident', 'Unspecified transport accident', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, 'từ hoặc vào trong', NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"từ hoặc vào trong\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W00', 'Ngã trên cùng một mặt bằng liên quan băng và/hoặc tuyết', 'Fall on same level involving ice and snow', 'Fall on same level involving ice and snow', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Loại trừ: ngã có đề cập đến: + trượt băng và nhảy ski (W02) + bậc thang, bậc thềm (W10)', 'Excl.: fall with mention of: ice- skates and skis (W02) stairs and steps (W10)', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Loại trừ: ngã có đề cập đến: + trượt băng và nhảy ski (W02) + bậc thang, bậc thềm (W10)\",\"coding-guidance-en\":\"Excl.: fall with mention of: ice- skates and skis (W02) stairs and steps (W10)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W01', 'Ngã trên cùng mặt bằng do trượt, vấp và/hoặc lộn nhào', 'Fall on same level from slipping, tripping and stumbling', 'Fall on same level from slipping, tripping and stumbling', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, 'Loại trừ: ngã có liên quan đến băng hoặc tuyết (W00)', 'Excl.: fall involving ice or snow (W00)', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"Loại trừ: ngã có liên quan đến băng hoặc tuyết (W00)\",\"coding-guidance-en\":\"Excl.: fall involving ice or snow (W00)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W02', 'Ngã liên quan trượt băng, ski, trượt patin hoặc ván trượt', 'Fall involving ice- skates, skis, roller- skates or skateboards', 'Fall involving ice- skates, skis, roller- skates or skateboards', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W03', 'Ngã khác trên cùng mặt bằng do va chạm hoặc bị người khác xô đẩy', 'Other fall on same level due to collision with, or pushing by, another person', 'Other fall on same level due to collision with, or pushing by, another person', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: ngã do va chạm của người đi bộ (băng tải) với người đi bộ khác (băng tải) - Loại trừ: bị đám đông người chạy tán loạn đè bẹp hoặc đẩy (W52) + ngã liên quan đến băng hoặc tuyết (W00)', 'Incl.: fall due to collision of pedestrian (conveyance) with another pedestrian (conveyance) Excl.: crushed or pushed by crowd or human stampede (W52) fall involving ice or snow (W00)', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: ngã do va chạm của người đi bộ (băng tải) với người đi bộ khác (băng tải) - Loại trừ: bị đám đông người chạy tán loạn đè bẹp hoặc đẩy (W52) + ngã liên quan đến băng hoặc tuyết (W00)\",\"coding-guidance-en\":\"Incl.: fall due to collision of pedestrian (conveyance) with another pedestrian (conveyance) Excl.: crushed or pushed by crowd or human stampede (W52) fall involving ice or snow (W00)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W04', 'Ngã khi đang được người khác bế hoặc cõng', 'Fall while being carried or supported by other persons', 'Fall while being carried or supported by other persons', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, 'Bao gồm: bị ngã khi đang được bế', 'Incl.: accidentally dropped while being carried', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"Bao gồm: bị ngã khi đang được bế\",\"coding-guidance-en\":\"Incl.: accidentally dropped while being carried\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
