('W06', 'Ngã liên quan đến giường', 'Fall involving bed', 'Fall involving bed', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W07', 'Ngã liên quan đến ghế', 'Fall involving chair', 'Fall involving chair', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W08', 'Ngã liên quan đến đồ nội thất khác', 'Fall involving other furniture', 'Fall involving other furniture', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W09', 'Ngã liên quan đến thiết bị sân chơi', 'Fall involving playground equipment', 'Fall involving playground equipment', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, 'Loại trừ: ngã liên quan đến máy giải trí (W31)', 'Excl.: fall involving recreational machinery (W31)', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"Loại trừ: ngã liên quan đến máy giải trí (W31)\",\"coding-guidance-en\":\"Excl.: fall involving recreational machinery (W31)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W10', 'Ngã trên và ngã từ bậc thang và/hoặc bậc thềm', 'Fall on and from stairs and steps', 'Fall on and from stairs and steps', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: ngã (trên) (từ): ++ cầu thang cuốn ++ mặt phẳng nghiêng ++ liên quan đến băng hoặc tuyết trên cầu thang hoặc bậc thềm ++ dốc', 'Incl.: fall (on)(from): escalator incline involving ice or snow on stairs and steps ramp', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: ngã (trên) (từ): ++ cầu thang cuốn ++ mặt phẳng nghiêng ++ liên quan đến băng hoặc tuyết trên cầu thang hoặc bậc thềm ++ dốc\",\"coding-guidance-en\":\"Incl.: fall (on)(from): escalator incline involving ice or snow on stairs and steps ramp\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W11', 'Ngã trên và/hoặc ngã từ thang', 'Fall on and from ladder', 'Fall on and from ladder', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs');
