('W56', 'Tiếp xúc với động vật biển', 'Contact with marine animal', 'Contact with marine animal', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, 'Bao gồm: bị động vật có vú dưới nước cắn hoặc tấn công', 'Incl.: Bitten or struck by marine animal', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"Bao gồm: bị động vật có vú dưới nước cắn hoặc tấn công\",\"coding-guidance-en\":\"Incl.: Bitten or struck by marine animal\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W57', 'Bị côn trùng không có nọc và/hoặc các loài tiết túc [virus arbo] không có nọc độc cắn hoặc đốt', 'Bitten or stung by nonvenomous insect and other nonvenomous arthropods', 'Bitten or stung by nonvenomous insect and other nonvenomous arthropods', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W58', 'Bị cá sấu châu Phi hoặc cá sấu Mỹ cắn hoặc tấn công', 'Bitten or struck by crocodile or alligator', 'Bitten or struck by crocodile or alligator', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W59', 'Bị loài bò sát khác cắn hoặc kẹp', 'Bitten or crushed by other reptiles', 'Bitten or crushed by other reptiles', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: thằn lằn + rắn, không nọc độc', 'Incl.: lizard snake, nonvenomous', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: thằn lằn + rắn, không nọc độc\",\"coding-guidance-en\":\"Incl.: lizard snake, nonvenomous\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W60', 'Tiếp xúc với cây gai, gai, lá nhọn', 'Contact with plant thorns and spines and sharp leaves', 'Contact with plant thorns and spines and sharp leaves', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W64', 'Tiếp xúc với các lực cơ học động khác và/hoặc không xác định', 'Exposure to other and unspecified animate mechanical forces', 'Exposure to other and unspecified animate mechanical forces', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W65', 'Đuối nước và/hoặc ngập nước khi ở trong bồn tắm', 'Drowning and submersion while in bath-tub', 'Drowning and submersion while in bath-tub', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W66', 'Đuối nước và/hoặc ngập nước sau khi ngã vào bồn tắm', 'Drowning and submersion following fall into bath-tub', 'Drowning and submersion following fall into bath-tub', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W67', 'Đuối nước và/hoặc ngập nước khi ở bể bơi', 'Drowning and submersion while in swimming-pool', 'Drowning and submersion while in swimming-pool', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W68', 'Đuối nước và/hoặc ngập nước sau khi ngã vào bể bơi', 'Drowning and submersion following fall into swimming-pool', 'Drowning and submersion following fall into swimming-pool', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W69', 'Đuối nước và/hoặc ngập nước khi ở trong nước tự nhiên', 'Drowning and submersion while in natural water', 'Drowning and submersion while in natural water', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: hồ + bể + sông + suối', 'Incl.: lake open sea river stream', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: hồ + bể + sông + suối\",\"coding-guidance-en\":\"Incl.: lake open sea river stream\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W70', 'Đuối nước và/hoặc ngập nước sau khi ngã xuống nước tự nhiên', 'Drowning and submersion following fall into natural water', 'Drowning and submersion following fall into natural water', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W73', 'Đuối nước và/hoặc ngập nước xác định khác', 'Other specified drowning and submersion', 'Other specified drowning and submersion', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: bể tôi [thùng tôi] + bình chứa', 'Incl.: quenching tank reservoir', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: bể tôi [thùng tôi] + bình chứa\",\"coding-guidance-en\":\"Incl.: quenching tank reservoir\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W74', 'Đuối nước và/hoặc ngập nước không xác định', 'Unspecified drowning and submersion', 'Unspecified drowning and submersion', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: đuối nước không xác định khác + ngã xuống nước không xác định khác', 'Incl.: drowning NOS fall into water NOS', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: đuối nước không xác định khác + ngã xuống nước không xác định khác\",\"coding-guidance-en\":\"Incl.: drowning NOS fall into water NOS\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W75', 'Vô tình bị ngạt thở và/hoặc bị siết cổ trên giường', 'Accidental suffocation and strangulation in bed', 'Accidental suffocation and strangulation in bed', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: nghẹt thở và siết cổ do: + khăn trải giường + cơ thể người mẹ + cái gối', 'Incl.: suffocation and strangulation due to: bed linen mother\'s body pillow', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: nghẹt thở và siết cổ do: + khăn trải giường + cơ thể người mẹ + cái gối\",\"coding-guidance-en\":\"Incl.: suffocation and strangulation due to: bed linen mother\'s body pillow\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W76', 'Vô tình bị treo cổ và/hoặc siết cổ khác', 'Other accidental hanging and strangulation', 'Other accidental hanging and strangulation', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W77', 'Đe doạ hô hấp do sụt đất, sạt lở đất và/hoặc các chất khác', 'Threat to breathing due to cave-in, falling earth and other substances', 'Threat to breathing due to cave-in, falling earth and other substances', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: sạt lở đất không xác định khác - Loại trừ: sạt lở do động đất (X34- X39) + vào hang mà', 'Incl.: cave-in NOS Excl.: cave-in caused by cataclysm (X34-X39) cave-in without asphyxiation or suffocation (W20)', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: sạt lở đất không xác định khác - Loại trừ: sạt lở do động đất (X34- X39) + vào hang mà\",\"coding-guidance-en\":\"Incl.: cave-in NOS Excl.: cave-in caused by cataclysm (X34-X39) cave-in without asphyxiation or suffocation (W20)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W78', 'Hít phải các chất trong dạ dày', 'Inhalation of gastric contents', 'Inhalation of gastric contents', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: ngạt do nôn [thực phẩm trào ngược] + bị sặc vì nôn [thực phẩm bị trào ngược] + ngạt thở do nôn [thực phẩm trào ngược] + hút và hít phải chất nôn (vào đường hô hấp) không xác định khác + chèn ép khí quản bởi chất nôn trong thực quản + gián đoạn hô hấp do chất nôn trong thực quản + tắc nghẽn hô hấp do chất nôn trong thực quản - Loại trừ: chấn thương, ngoại trừ ngạt hoặc tắc nghẽn đường hô hấp, do chất nôn (W44) + tắc nghẽn thực quản do chất nôn', 'Incl.: asphyxia by vomitus [regurgitated food] choked on vomitus [regurgitated food] suffocation by vomitus [regurgitated food] aspiration and inhalation of vomitus (into respiratory tract) NOS compression of trachea by vomitus in oesophagus interruption of respiration by vomitus in oesophagus obstruction of respiration by vomitus in oesophagus Excl.: injury, except asphyxia or obstruction of respiratory tract, caused by vomitus (W44) obstruction of oesophagus by vomitus without', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: ngạt do nôn [thực phẩm trào ngược] + bị sặc vì nôn [thực phẩm bị trào ngược] + ngạt thở do nôn [thực phẩm trào ngược] + hút và hít phải chất nôn (vào đường hô hấp) không xác định khác + chèn ép khí quản bởi chất nôn trong thực quản + gián đoạn hô hấp do chất nôn trong thực quản + tắc nghẽn hô hấp do chất nôn trong thực quản - Loại trừ: chấn thương, ngoại trừ ngạt hoặc tắc nghẽn đường hô hấp, do chất nôn (W44) + tắc nghẽn thực quản do chất nôn\",\"coding-guidance-en\":\"Incl.: asphyxia by vomitus [regurgitated food] choked on vomitus [regurgitated food] suffocation by vomitus [regurgitated food] aspiration and inhalation of vomitus (into respiratory tract) NOS compression of trachea by vomitus in oesophagus interruption of respiration by vomitus in oesophagus obstruction of respiration by vomitus in oesophagus Excl.: injury, except asphyxia or obstruction of respiratory tract, caused by vomitus (W44) obstruction of oesophagus by vomitus without\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs');
INSERT INTO `icd10` (`code`, `display_vi`, `display_en`, `definition_en`, `level`, `parent_code`, `chapter_id`, `chapter_code`, `section_id`, `type_code`, `is_leaf`, `is_active`, `coding_guidance`, `coding_guidance_en`, `properties_json`, `version`, `source`) VALUES
('W79', 'Hít và/hoặc nuốt thức ăn gây tắc nghẽn đường hô hấp', 'Inhalation and ingestion of food causing obstruction of respiratory tract', 'Inhalation and ingestion of food causing obstruction of respiratory tract', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: ngạt do thực phẩm [kể cả xương hoặc hạt] + bị nghẹn thực phẩm [kể cả xương hoặc hạt] + ngạt thở bởi thực phẩm [kể cả xương hoặc hạt] + hít và hít phải thực phẩm [bất kỳ] (vào đường hô hấp) không xác định khác + nén khí quản bởi thực phẩm trong thực quản + gián đoạn hô hấp do thực phẩm trong thực quản + cản trở hô hấp bởi thực phẩm trong thực quản + tắc nghẽn cổ họng do thực phẩm (bolus) - Loại trừ: hít phải chất nôn (W78) + thương tích, ngoại trừ ngạt hoặc tắc nghẽn đường hô hấp do thực phẩm (W44) + tắc nghẽn thực', 'Incl.: asphyxia by food [including bone or seed] choked on food [including bone or seed] suffocation by food [including bone or seed] aspiration and inhalation of food [any] (into respiratory tract) NOS compression of trachea by food in oesophagus interruption of respiration by food in oesophagus obstruction of respiration by food in oesophagus obstruction of pharynx by food (bolus) Excl.: inhalation of vomitus (W78) injury, except asphyxia or obstruction of respiratory tract, caused by food (W44) obstruction of oesophagus by food without mention of asphyxia or obstruction of', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: ngạt do thực phẩm [kể cả xương hoặc hạt] + bị nghẹn thực phẩm [kể cả xương hoặc hạt] + ngạt thở bởi thực phẩm [kể cả xương hoặc hạt] + hít và hít phải thực phẩm [bất kỳ] (vào đường hô hấp) không xác định khác + nén khí quản bởi thực phẩm trong thực quản + gián đoạn hô hấp do thực phẩm trong thực quản + cản trở hô hấp bởi thực phẩm trong thực quản + tắc nghẽn cổ họng do thực phẩm (bolus) - Loại trừ: hít phải chất nôn (W78) + thương tích, ngoại trừ ngạt hoặc tắc nghẽn đường hô hấp do thực phẩm (W44) + tắc nghẽn thực\",\"coding-guidance-en\":\"Incl.: asphyxia by food [including bone or seed] choked on food [including bone or seed] suffocation by food [including bone or seed] aspiration and inhalation of food [any] (into respiratory tract) NOS compression of trachea by food in oesophagus interruption of respiration by food in oesophagus obstruction of respiration by food in oesophagus obstruction of pharynx by food (bolus) Excl.: inhalation of vomitus (W78) injury, except asphyxia or obstruction of respiratory tract, caused by food (W44) obstruction of oesophagus by food without mention of asphyxia or obstruction of\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W80', 'Hít và/hoặc nuốt phải các vật thể khác gây tắc nghẽn đường hô hấp', 'Inhalation and ingestion of other objects causing obstruction of respiratory tract', 'Inhalation and ingestion of other objects causing obstruction of respiratory tract', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: ngạt do bất kỳ vật nào, ngoại trừ thực phẩm hoặc chất nôn, xâm nhập đường mũi hoặc miệng hít phải không xác định khác + bị nghẹn bởi bất kỳ vật gì, ngoại trừ thực phẩm hoặc chất nôn, xâm nhập bằng mũi hoặc miệng hít phải không xác định khác + ngạt thở bởi bất kỳ vật thể nào, trừ thực phẩm hoặc chất nôn, xâm nhập đường mũi hoặc miệng hít phải không xác định khác + hút và hít phải dị vật, ngoại trừ thực phẩm hoặc chất nôn (vào đường hô hấp), không xác định khác + chèn ép khí quản bởi dị vật trong thực quản', 'Incl.: asphyxia by any object, except food or vomitus, entering by nose or mouth aspiration NOS choked on any object, except food or vomitus, entering by nose or mouth aspiration NOS suffocation by any object, except food or vomitus, entering by nose or mouth aspiration NOS aspiration and inhalation of foreign body, except food or vomitus (into respiratory tract), NOS compression of trachea by foreign body in oesophagus interruption of respiration by foreign body in oesophagus obstruction of respiration by foreign body in oesophagus foreign object in nose obstruction of pharynx by foreign body', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: ngạt do bất kỳ vật nào, ngoại trừ thực phẩm hoặc chất nôn, xâm nhập đường mũi hoặc miệng hít phải không xác định khác + bị nghẹn bởi bất kỳ vật gì, ngoại trừ thực phẩm hoặc chất nôn, xâm nhập bằng mũi hoặc miệng hít phải không xác định khác + ngạt thở bởi bất kỳ vật thể nào, trừ thực phẩm hoặc chất nôn, xâm nhập đường mũi hoặc miệng hít phải không xác định khác + hút và hít phải dị vật, ngoại trừ thực phẩm hoặc chất nôn (vào đường hô hấp), không xác định khác + chèn ép khí quản bởi dị vật trong thực quản\",\"coding-guidance-en\":\"Incl.: asphyxia by any object, except food or vomitus, entering by nose or mouth aspiration NOS choked on any object, except food or vomitus, entering by nose or mouth aspiration NOS suffocation by any object, except food or vomitus, entering by nose or mouth aspiration NOS aspiration and inhalation of foreign body, except food or vomitus (into respiratory tract), NOS compression of trachea by foreign body in oesophagus interruption of respiration by foreign body in oesophagus obstruction of respiration by foreign body in oesophagus foreign object in nose obstruction of pharynx by foreign body\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W81', 'Bị giam giữ hoặc bị mắc kẹt trong môi trường thiếu oxy', 'Confined to or trapped in a low- oxygen environment', 'Confined to or trapped in a low- oxygen environment', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: vô tình đóng cửa [nhốt] trong tủ lạnh hoặc không gian kín gió khác + lặn với nguồn cung cấp không khí không đủ - Loại trừ: ngạt thở do túi nhựa', 'Incl.: accidentally shut in refrigerator or other airtight space diving with insufficient air supply Excl.: suffocation by plastic bag (W83)', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: vô tình đóng cửa [nhốt] trong tủ lạnh hoặc không gian kín gió khác + lặn với nguồn cung cấp không khí không đủ - Loại trừ: ngạt thở do túi nhựa\",\"coding-guidance-en\":\"Incl.: accidentally shut in refrigerator or other airtight space diving with insufficient air supply Excl.: suffocation by plastic bag (W83)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W83', 'Các mối đe doạ xác định khác đối với hô hấp', 'Other specified threats to breathing', 'Other specified threats to breathing', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '(BWao8 3g)ồm: ngạt thở do túi nhựa', 'Incl.: suffocation by plastic bag', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"(BWao8 3g)ồm: ngạt thở do túi nhựa\",\"coding-guidance-en\":\"Incl.: suffocation by plastic bag\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W84', 'Mối đe doạ không xác định đối với hô hấp', 'Unspecified threat to breathing', 'Unspecified threat to breathing', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: ngạt thở không xác định khác + nghẹt thở không xác định khác', 'Incl.: asphyxiation NOS suffocation NOS', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: ngạt thở không xác định khác + nghẹt thở không xác định khác\",\"coding-guidance-en\":\"Incl.: asphyxiation NOS suffocation NOS\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W85', 'Tiếp xúc với đường dây tải điện', 'Exposure to electric transmission lines', 'Exposure to electric transmission lines', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W86', 'Tiếp xúc với dòng điện xác định khác', 'Exposure to other specified electric current', 'Exposure to other specified electric current', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W87', 'Tiếp xúc với dòng điện không xác định', 'Exposure to unspecified electric current', 'Exposure to unspecified electric current', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: bỏng hoặc chấn thương khác do dòng điện không xác định khác + sốc điện không xác định khác + điện giật không xác định khác', 'Incl.: burns or other injury from electric current NOS electric shock NOS electrocution NOS', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: bỏng hoặc chấn thương khác do dòng điện không xác định khác + sốc điện không xác định khác + điện giật không xác định khác\",\"coding-guidance-en\":\"Incl.: burns or other injury from electric current NOS electric shock NOS electrocution NOS\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W88', 'Phơi nhiễm với nguồn phóng xạ [bức xạ] ion hoá', 'Exposure to ionizing radiation', 'Exposure to ionizing radiation', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: đồng vị phóng xạ + X-quang', 'Incl.: radioactive isotopes X-rays', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: đồng vị phóng xạ + X-quang\",\"coding-guidance-en\":\"Incl.: radioactive isotopes X-rays\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W89', 'Mắt phơi nhiễm với ánh sáng nhân tạo và/hoặc tia cực tím', 'Exposure to man- made visible and ultraviolet light', 'Exposure to man- made visible and ultraviolet light', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, 'Bao gồm: ánh sáng hàn (hồ quang)', 'Incl.: welding light (arc)', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"Bao gồm: ánh sáng hàn (hồ quang)\",\"coding-guidance-en\":\"Incl.: welding light (arc)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W90', 'Phơi nhiễm với bức xạ không ion hoá khác', 'Exposure to other nonionizing radiation', 'Exposure to other nonionizing radiation', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: bức xạ hồng ngoại + bức xạ laser + bức xạ tần số vô tuyến', 'Incl.: infrared radiation laser radiation radiofrequency radiation', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: bức xạ hồng ngoại + bức xạ laser + bức xạ tần số vô tuyến\",\"coding-guidance-en\":\"Incl.: infrared radiation laser radiation radiofrequency radiation\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W91', 'Phơi nhiễm với nguồn phóng xạ [bức xạ] không xác định', 'Exposure to unspecified type of radiation', 'Exposure to unspecified type of radiation', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W92', 'Tiếp xúc với nhiệt độ quá cao có nguồn gốc nhân tạo', 'Exposure to excessive heat of man-made origin', 'Exposure to excessive heat of man-made origin', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W93', 'Tiếp xúc quá mức với nguồn nhiệt lạnh nhân tạo', 'Exposure to excessive cold of man-made origin', 'Exposure to excessive cold of man-made origin', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: tiếp xúc hoặc hít phải: ++ đá khô ++ chất lỏng: +++ không khí +++ hydro +++ nitơ + phơi nhiễm kéo dài trong thiết bị đông lạnh sâu', 'Incl.: contact with or inhalation of: dry ice liquid: air hydrogen nitrogen prolonged exposure in deep-', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: tiếp xúc hoặc hít phải: ++ đá khô ++ chất lỏng: +++ không khí +++ hydro +++ nitơ + phơi nhiễm kéo dài trong thiết bị đông lạnh sâu\",\"coding-guidance-en\":\"Incl.: contact with or inhalation of: dry ice liquid: air hydrogen nitrogen prolonged exposure in deep-\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W94', 'Tiếp xúc với áp suất không khí cao và/hoặc thấp và/hoặc thay đổi áp suất không khí', 'Exposure to high and low air pressure and changes in air pressure', 'Exposure to high and low air pressure and changes in air pressure', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: áp suất không khí cao từ quá trình giảm tốc nhanh chóng trong nước + giảm áp suất khí quyển khi nổi lên từ: ++ lặn sâu dưới nước ++ khu vực ngầm + cư trú hoặc thăm viếng kéo dài ở độ cao là nguyên nhân của: ++ giảm oxy mô ++ đau răng do khí áp ++ viêm vú ++ thiếu oxy ++ say độ cao + thay đổi đột', 'Incl.: high air pressure from rapid descent in water reduction in atmospheric pressure while surfacing from: deep- water diving underground residence or prolonged visit at high altitude as the cause of: anoxia barodontalgia barotitis hypoxia mountain sickness sudden change', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: áp suất không khí cao từ quá trình giảm tốc nhanh chóng trong nước + giảm áp suất khí quyển khi nổi lên từ: ++ lặn sâu dưới nước ++ khu vực ngầm + cư trú hoặc thăm viếng kéo dài ở độ cao là nguyên nhân của: ++ giảm oxy mô ++ đau răng do khí áp ++ viêm vú ++ thiếu oxy ++ say độ cao + thay đổi đột\",\"coding-guidance-en\":\"Incl.: high air pressure from rapid descent in water reduction in atmospheric pressure while surfacing from: deep- water diving underground residence or prolonged visit at high altitude as the cause of: anoxia barodontalgia barotitis hypoxia mountain sickness sudden change\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('W99', 'Tiếp xúc với các yếu tố môi trường khác và/hoặc không xác định do con người tạo ra', 'Exposure to other and unspecified man-made environmental factors', 'Exposure to other and unspecified man-made environmental factors', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, 'ngột của áp suất', 'in air pressure in', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"ngột của áp suất\",\"coding-guidance-en\":\"in air pressure in\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('X00', 'Tiếp xúc với đám cháy không kiểm soát được ở toà nhà hoặc công trình xây dựng', 'Exposure to uncontrolled fire in building or structure', 'Exposure to uncontrolled fire in building or structure', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: toà nhà sụp đổ hoặc công trình xây dựng đang cháy + rơi từ toà nhà hoặc công trình xây dựng đang cháy + trúng vật thể rơi từ toà nhà hoặc công trình xây dựng đang cháy + nhảy từ toà nhà hoặc công trình xây dựng đang cháy + thiêu rụi các phụ kiện + cháy các phụ kiện + sự nóng chảy của phụ kiện + cháy âm ỉ của phụ kiện + làm cháy đồ nội thất + cháy đồ nội thất + đồ nội thất tan', 'Incl.: collapse of burning building or structure fall from burning building or structure hit by object falling from burning building or structure jump from burning building or structure conflagration of fittings fire of fittings melting of fittings smouldering of fittings conflagration of furniture fire of furniture melting of furniture smouldering of furniture', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: toà nhà sụp đổ hoặc công trình xây dựng đang cháy + rơi từ toà nhà hoặc công trình xây dựng đang cháy + trúng vật thể rơi từ toà nhà hoặc công trình xây dựng đang cháy + nhảy từ toà nhà hoặc công trình xây dựng đang cháy + thiêu rụi các phụ kiện + cháy các phụ kiện + sự nóng chảy của phụ kiện + cháy âm ỉ của phụ kiện + làm cháy đồ nội thất + cháy đồ nội thất + đồ nội thất tan\",\"coding-guidance-en\":\"Incl.: collapse of burning building or structure fall from burning building or structure hit by object falling from burning building or structure jump from burning building or structure conflagration of fittings fire of fittings melting of fittings smouldering of fittings conflagration of furniture fire of furniture melting of furniture smouldering of furniture\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('X01', 'Tiếp xúc với đám cháy không kiểm soát được, không phải ở toà nhà hoặc công trình xây dựng', 'Exposure to uncontrolled fire, not in building or structure', 'Exposure to uncontrolled fire, not in building or structure', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, 'Bao gồm: cháy rừng', 'Incl.: forest fire', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"Bao gồm: cháy rừng\",\"coding-guidance-en\":\"Incl.: forest fire\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('X02', 'Tiếp xúc với đám cháy kiểm soát được của toà nhà hoặc công trình xây dựng', 'Exposure to controlled fire in building or structure', 'Exposure to controlled fire in building or structure', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: cháy do: ++ lò sưởi ++ bếp lò', 'Incl.: fire in: fireplace stove', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: cháy do: ++ lò sưởi ++ bếp lò\",\"coding-guidance-en\":\"Incl.: fire in: fireplace stove\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('X03', 'Tiếp xúc với đám cháy có kiểm soát, không phải ở toà nhà hoặc công trình xây dựng', 'Exposure to controlled fire, not in building or structure', 'Exposure to controlled fire, not in building or structure', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, 'Bao gồm: đốt lửa trại', 'Incl.: camp-fire', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"Bao gồm: đốt lửa trại\",\"coding-guidance-en\":\"Incl.: camp-fire\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('X04', 'Tiếp xúc với vật liệu dễ cháy có tính bắt lửa cao', 'Exposure to ignition of highly flammable material', 'Exposure to ignition of highly flammable material', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, 'Bao gồm: đánh lửa của: ++ xăng ++ dầu hoả ++ xăng dầu', 'Incl.: ignition of: gasoline kerosene petrol', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"Bao gồm: đánh lửa của: ++ xăng ++ dầu hoả ++ xăng dầu\",\"coding-guidance-en\":\"Incl.: ignition of: gasoline kerosene petrol\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('X05', 'Tiếp xúc với quần áo hoặc trang phục dễ nóng chảy', 'Exposure to ignition or melting of nightwear', 'Exposure to ignition or melting of nightwear', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, NULL, NULL, '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('X06', 'Phơi nhiễm với quần áo hoặc trang phục khác dễ bắt lửa', 'Exposure to ignition or melting of other clothing and apparel', 'Exposure to ignition or melting of other clothing and apparel', 'type', NULL, 'V01-Y98', 'XX', 'V01-X59', NULL, 1, 1, '- Bao gồm: đánh lửa đồ trang sức bằng nhựa + nóng chảy đồ trang sức bằng nhựa', 'Incl.: ignition of plastic jewellery melting of plastic jewellery', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"V01-X59\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: đánh lửa đồ trang sức bằng nhựa + nóng chảy đồ trang sức bằng nhựa\",\"coding-guidance-en\":\"Incl.: ignition of plastic jewellery melting of plastic jewellery\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
