('X67.4', 'Cố ý tự đầu độc bằng cách tiếp xúc với carbon monoxide từ các nguồn không xác định', 'Intentional self- poisoning by and exposure to carbon monoxide from unspecified sources', 'Intentional self- poisoning by and exposure to carbon monoxide from unspecified sources', 'disease', 'X67', 'V01-Y98', 'XX', 'X60-X84', 'X67', 1, 1, '+ lò hơi', NULL, '{\"level\":\"disease\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"X60-X84\",\"type-code\":\"X67\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"+ lò hơi\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('X67.8', 'Cố ý tự đầu độc bằng cách tiếp xúc với khí và/hoặc hơi xác định khác', 'Intentional self- poisoning by and exposure to other specified gases and vapours', 'Intentional self- poisoning by and exposure to other specified gases and vapours', 'disease', 'X67', 'V01-Y98', 'XX', 'X60-X84', 'X67', 1, 1, '- Khí Heli (không phải là dược liệu) không phân loại mục khác - Khí sinh Lacrimogenic [hơi cay] - Ôxít nitơ - Lưu huỳnh dioxit - Loại trừ: heli,', 'Helium (nonmedicinal) NEC Lacrimogenic gas [tear gas] Nitrogen oxides Sulfur dioxide Excl.: helium, medicinal (X64.-)', '{\"level\":\"disease\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"X60-X84\",\"type-code\":\"X67\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Khí Heli (không phải là dược liệu) không phân loại mục khác - Khí sinh Lacrimogenic [hơi cay] - Ôxít nitơ - Lưu huỳnh dioxit - Loại trừ: heli,\",\"coding-guidance-en\":\"Helium (nonmedicinal) NEC Lacrimogenic gas [tear gas] Nitrogen oxides Sulfur dioxide Excl.: helium, medicinal (X64.-)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('X67.9', 'Cố ý tự đầu độc bằng cách tiếp xúc với khí và/hoặc hơi không xác định', 'Intentional self- poisoning by and exposure to unspecified gases and vapours', 'Intentional self- poisoning by and exposure to unspecified gases and vapours', 'disease', 'X67', 'V01-Y98', 'XX', 'X60-X84', 'X67', 1, 1, 'dược phẩm (X64.-)', NULL, '{\"level\":\"disease\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"X60-X84\",\"type-code\":\"X67\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"dược phẩm (X64.-)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs'),
('X68', 'Cố ý tự đầu độc bằng và/hoặc cố tình phơi nhiễm với thuốc trừ sâu', 'Intentional self- poisoning by and exposure to pesticides', 'Intentional self- poisoning by and exposure to pesticides', 'type', NULL, 'V01-Y98', 'XX', 'X60-X84', NULL, 1, 1, '- Bao gồm: chất sinh khói + thuốc diệt nấm + thuốc diệt cỏ + thuốc diệt côn trùng + thuốc diệt chuột + chất bảo quản gỗ - Loại trừ: thực phẩm và phân bón thực vật (X69)', 'Incl.: fumigants fungicides herbicides insecticides rodenticides wood preservatives Excl.: plant foods and fertilizers (X69)', '{\"level\":\"type\",\"chapter-id\":\"V01-Y98\",\"chapter-code\":\"XX\",\"section-id\":\"X60-X84\",\"leaf\":true,\"not-primary-diagnosis\":true,\"coding-guidance\":\"- Bao gồm: chất sinh khói + thuốc diệt nấm + thuốc diệt cỏ + thuốc diệt côn trùng + thuốc diệt chuột + chất bảo quản gỗ - Loại trừ: thực phẩm và phân bón thực vật (X69)\",\"coding-guidance-en\":\"Incl.: fumigants fungicides herbicides insecticides rodenticides wood preservatives Excl.: plant foods and fertilizers (X69)\"}', '2026-07-01', 'http://fhir.hl7.org.vn/core/CodeSystem/vn-icd10-cs');
