INSERT INTO `nhom_bhyt` (`id`, `ten`, `mota`) VALUES
('BT', 'Người thuộc diện hưởng trợ cấp bảo trợ xã hội hằng tháng theo quy định của pháp luật', 'Người thuộc diện hưởng trợ cấp bảo trợ xã hội hằng tháng theo quy định của pháp luật.'),
('CA', 'Công an nhân dân', 'Sỹ quan, hạ sỹ quan nghiệp vụ và sỹ quan, hạ sỹ quan chuyên môn kỹ thuật, hạ sỹ quan, chiến sỹ nghĩa vụ đang công tác trong lực lượng công an nhân dân, học viên công an nhân dân hưởng sinh hoạt phí từ ngân sách Nhà nước.'),
('CB', 'Cựu chiến binh theo quy định pháp luật về cựu chiến binh', 'Cựu chiến binh theo quy định pháp luật về cựu chiến binh.'),
('CC', 'Người có công với cách mạng, bao gồm: Người hoạt động cách mạng trước ngày 1/1/1945', 'Người có công với cách mạng, bao gồm: Người hoạt động cách mạng trước ngày 1/1/1945; người hoạt động cách mạng từ ngày 1/1/1945 đến ngày khởi nghĩa Tháng Tám 1945; Bà mẹ Việt Nam anh hùng; thương binh, người hưởng chính sách như thương binh, thương binh loại B, bệnh binh suy giảm khả năng lao động từ 81% trở lên.'),
('CH', 'Người lao động tại cơ quan, tổ chức', 'Người lao động làm việc trong các cơ quan nhà nước, đơn vị sự nghiệp, lực lượng vũ trang, tổ chức chính trị, tổ chức chính trị - xã hội, tổ chức chính trị - xã hội - nghề nghiệp, tổ chức xã hội - nghề nghiệp và tổ chức xã hội khác.'),
('CK', 'Người có công với cách mạng theo quy định pháp luật về người có công với cách mạng', 'Người có công với cách mạng theo quy định pháp luật về người có công với cách mạng'),
('CN', 'Người thuộc hộ gia đình cận nghèo', 'Người thuộc hộ gia đình cận nghèo.'),
('CS', 'Công nhân cao su nghỉ việc đang hưởng trợ cấp hằng tháng theo Quyết định số 206/CP ngày 30/5/1979 của Hội đồng Chính phủ (nay là Chính phủ) về chính sách đối với công nhân mới giải phóng làm nghề nặng nhọc, có hại sức khỏe nay già yếu phải thôi việc', 'Công nhân cao su nghỉ việc đang hưởng trợ cấp hằng tháng theo Quyết định số 206/CP ngày 30/5/1979 của Hội đồng Chính phủ (nay là Chính phủ) về chính sách đối với công nhân mới giải phóng làm nghề nặng nhọc, có hại sức khỏe nay già yếu phải thôi việc.'),
('CT', 'Người từ đủ 80 tuổi trở lên đang hưởng trợ cấp tuất hằng tháng', 'Người từ đủ 80 tuổi trở lên đang hưởng trợ cấp tuất hằng tháng.'),
('CY', 'Người làm công tác cơ yếu hưởng lương như đối với quân nhân đang công tác tại các tổ chức cơ yếu thuộc các bộ, ngành, địa phương', 'Người làm công tác cơ yếu hưởng lương như đối với quân nhân đang công tác tại các tổ chức cơ yếu thuộc các bộ, ngành, địa phương.'),
('DK', 'Người đang sinh sống tại vùng có điều kiện kinh tế- xã hội đặc biệt khó khăn', 'Người đang sinh sống tại vùng có điều kiện kinh tế- xã hội đặc biệt khó khăn.'),
('DN', 'Người lao động tại doanh nghiệp', 'Người lao động làm việc trong các doanh nghiệp thành lập, hoạt động theo Luật Doanh nghiệp (https://thuvienphapluat.vn/van-ban/Doanh-nghiep/Luat-Doanh-nghiep-so-59-2020-QH14-427301.aspx) và Luật Đầu tư (https://thuvienphapluat.vn/van-ban/Doanh-nghiep/Luat-Dau-tu-so-61-2020-QH14-321051.aspx).'),
('DT', 'Người dân tộc thiểu số đang sinh sống tại vùng có điều kiện kinh tế- xã hội khó khăn, đặc biệt khó khăn', 'Người dân tộc thiểu số đang sinh sống tại vùng có điều kiện kinh tế- xã hội khó khăn, đặc biệt khó khăn.'),
('GB', 'Hộ làm nông, lâm, ngư nghiệp và diêm nghiệp', 'Người thuộc hộ gia đình làm nông nghiệp, lâm nghiệp, ngư nghiệp và diêm nghiệp có mức sống trung bình theo quy định của pháp luật.'),
('GD', 'Người tham gia BHYT theo hộ gia đình', 'Người tham gia BHYT theo hộ gia đình gồm những người thuộc hộ gia đình, trừ đối tượng quy định tại các điểm a, b, c, d nêu trên.'),
('HC', 'CBCCVC theo quy định của pháp luật về CBCCVC', 'CBCCVC theo quy định của pháp luật về CBCCVC.'),
('HD', 'Đại biểu Quốc hội, đại biểu HĐND các cấp đương nhiệm', 'Đại biểu Quốc hội, đại biểu HĐND các cấp đương nhiệm.'),
('HG', 'Người đã hiến bộ phận cơ thể người theo quy định của pháp luật', 'Người đã hiến bộ phận cơ thể người theo quy định của pháp luật.'),
('HN', 'Người thuộc hộ gia đình nghèo', 'Người thuộc hộ gia đình nghèo.'),
('HS', 'Học sinh', 'Học sinh đang theo học tại các cơ sở giáo dục và đào tạo thuộc hệ thống giáo dục quốc dân.'),
('HT', 'Người hưởng lương hưu, trợ cấp mất sức', 'Người hưởng lương hưu, trợ cấp mất sức lao động hàng tháng.'),
('HX', 'Người lao động tại hợp tác xã', 'Người lao động làm việc trong các hợp tác xã, liên hiệp hợp tác xã thành lập và hoạt động theo Luật Hợp tác xã (https://thuvienphapluat.vn/van-ban/Doanh-nghiep/Luat-Hop-tac-xa-499239.aspx).'),
('KC', 'Người trực tiếp tham gia kháng chiến chống Mỹ cứu nước', 'Người trực tiếp tham gia kháng chiến chống Mỹ cứu nước; người tham gia chiến tranh bảo vệ Tổ quốc, làm nhiệm vụ quốc tế ở Campuchia, giúp bạn Lào sau ngày 30/4/1975; thanh niên xung phong thời kỳ kháng chiến chống Pháp và thanh niên xung phong đã hoàn thành nhiệm vụ trong kháng chiến; dân công hoả tuyến tham gia kháng chiến chống Pháp, chống Mỹ, chiến tranh bảo vệ Tổ quốc và làm nhiệm vụ quốc tế theo quy định tại các quyết định của Thủ tướng Chính phủ, trừ các đối tượng được cấp mã CC, CK và CB.'),
('LH', 'Người cao tuổi từ đủ 75 tuổi trở lên đang hưởng trợ cấp hưu trí xã hội', 'Nhóm dành cho người cao tuổi từ đủ 75 tuổi trở lên đang hưởng trợ cấp hưu trí xã hội'),
('LS', 'Người nước ngoài đang học tập tại Việt Nam được cấp học bổng từ ngân sách của Nhà nước Việt Nam', 'Người nước ngoài đang học tập tại Việt Nam được cấp học bổng từ ngân sách của Nhà nước Việt Nam.'),
('MS', 'Người đã thôi hưởng trợ cấp MSLĐ đang hưởng trợ cấp hằng tháng từ NSNN', 'Người đã thôi hưởng trợ cấp MSLĐ đang hưởng trợ cấp hằng tháng từ NSNN.'),
('NN', 'NLĐ làm việc trong các cơ quan, tổ chức nước ngoài hoặc tổ chức quốc tế tại Việt Nam, trừ trường hợp Điều ước quốc tế mà nước Cộng hòa XHCN Việt Nam là thành viên tham gia có quy định khác', 'NLĐ làm việc trong các cơ quan, tổ chức nước ngoài hoặc tổ chức quốc tế tại Việt Nam, trừ trường hợp Điều ước quốc tế mà nước Cộng hòa XHCN Việt Nam là thành viên tham gia có quy định khác.'),
('NO', 'Người nghỉ việc hưởng chế độ ốm đau dài ngày', 'Người lao động nghỉ việc đang hưởng chế độ ốm đau theo quy định của pháp luật về bảo hiểm xã hội do mắc bệnh thuộc danh mục bệnh cần chữa trị dài ngày theo quy định của Bộ trưởng Bộ Y tế.'),
('PV', 'Người phục vụ người có công với cách mạng, bao gồm: Người phục vụ Bà mẹ Việt Nam anh hùng sống ở gia đình', 'Người phục vụ người có công với cách mạng, bao gồm: Người phục vụ Bà mẹ Việt Nam anh hùng sống ở gia đình; người phục vụ thương binh, bệnh binh suy giảm khả năng lao động từ 81% trở lên ở gia đình; người phục vụ người hoạt động kháng chiến bị nhiễm chất độc hoá học suy giảm khả năng lao động từ 81% trở lên sống ở gia đình.'),
('QN', 'Quân nhân và người làm công tác cơ yếu', 'Sỹ quan, quân nhân chuyên nghiệp, hạ sỹ quan, binh sỹ Quân đội nhân dân Việt Nam đang tại ngũ; người làm công tác cơ yếu hưởng lương như đối với quân nhân đang công tác tại Ban Cơ yếu Chính phủ; học viên cơ yếu hưởng sinh hoạt phí từ ngân sách Nhà nước theo chế độ, chính sách như đối với học viên Quân đội.'),
('SV', 'Sinh viên', 'Sinh viên đang theo học tại các cơ sở giáo dục và đào tạo, cơ sở dạy nghề thuộc hệ thống giáo dục quốc dân.'),
('TA', 'Thân nhân của đối tượng được cấp mã CA', 'Thân nhân của đối tượng được cấp mã CA.'),
('TB', 'Người hưởng trợ cấp tai nạn lao động, bệnh nghề nghiệp', 'Người đang hưởng trợ cấp bảo hiểm xã hội hàng tháng do bị tai nạn lao động, bệnh nghề nghiệp.'),
('TC', 'Thân nhân của người có công với cách mạng, bao gồm: Cha đẻ, mẹ đẻ, vợ hoặc chồng, con từ trên 6 tuổi đến dưới 18 tuổi hoặc từ đủ 18 tuổi trở lên nếu còn tiếp tục đi học hoặc bị khuyết tật nặng, khuyết tật đặc biệt nặng của các đối tượng', 'Thân nhân của người có công với cách mạng, bao gồm: Cha đẻ, mẹ đẻ, vợ hoặc chồng, con từ trên 6 tuổi đến dưới 18 tuổi hoặc từ đủ 18 tuổi trở lên nếu còn tiếp tục đi học hoặc bị khuyết tật nặng, khuyết tật đặc biệt nặng của các đối tượng; người hoạt động cách mạng trước ngày 1/1/1945; người hoạt động cách mạng từ ngày 1/1/1945 đến ngày khởi nghĩa tháng Tám năm 1945; Anh hùng LLVT nhân dân, Anh hùng Lao động trong thời kỳ kháng chiến; thương binh, bệnh binh suy giảm khả năng lao động từ 61% trở lên; người hoạt động kháng chiến bị nhiễm chất độc hóa học suy giảm khả năng lao động từ 61% trở lên; con đẻ từ trên 6 tuổi của người hoạt động kháng chiến bị nhiễm chất độc hóa học bị dị dạng, dị tật do hậu quả của chất độc hóa học không tự lực được trong sinh hoạt hoặc suy giảm khả năng tự lực trong sinh hoạt, trừ các đối tượng được cấp mã TS.'),
('TE', 'Trẻ em dưới 6 tuổi, kể cả trẻ đủ 72 tháng tuổi mà trong năm đó chưa đến kỳ nhập học', 'Trẻ em dưới 6 tuổi, kể cả trẻ đủ 72 tháng tuổi mà trong năm đó chưa đến kỳ nhập học.'),
('TK', 'NLĐ làm việc trong các tổ chức khác có SDLĐ được thành lập và hoạt động theo quy định của pháp luật', 'NLĐ làm việc trong các tổ chức khác có SDLĐ được thành lập và hoạt động theo quy định của pháp luật.'),
('TN', 'Người đang hưởng trợ cấp thất nghiệp theo quy định của pháp luật về BH thất nghiệp', 'Người đang hưởng trợ cấp thất nghiệp theo quy định của pháp luật về BH thất nghiệp.'),
('TQ', 'Thân nhân của đối tượng được cấp mã QN', 'Thân nhân của đối tượng được cấp mã QN.'),
('TS', 'Thân nhân của người có công với cách mạng là cha đẻ, mẹ đẻ, vợ hoặc chồng, con của liệt sĩ', 'Thân nhân của người có công với cách mạng là cha đẻ, mẹ đẻ, vợ hoặc chồng, con của liệt sĩ; người có công nuôi dưỡng liệt sĩ.'),
('TV', 'Thân nhân công nhân và viên chức quốc phòng đang phục vụ trong quân đội không có chế độ BHYT', 'Thân nhân công nhân và viên chức quốc phòng đang phục vụ trong quân đội không có chế độ BHYT.'),
('TY', 'Thân nhân của đối tượng được cấp mã CY', 'Thân nhân của đối tượng được cấp mã CY.'),
('XB', 'Cán bộ xã, phường, thị trấn đã nghỉ việc đang hưởng trợ cấp BHXH hằng tháng', 'Cán bộ xã, phường, thị trấn đã nghỉ việc đang hưởng trợ cấp BHXH hằng tháng.'),
('XD', 'Người đang sinh sống tại xã đảo, huyện đảo', 'Người đang sinh sống tại xã đảo, huyện đảo.'),
('XK', 'Người hoạt động không chuyên trách ở xã, phường, thị trấn theo quy định của pháp luật về CBCC', 'Người hoạt động không chuyên trách ở xã, phường, thị trấn theo quy định của pháp luật về CBCC.'),
('XN', 'Cán bộ xã, phường, thị trấn đã nghỉ việc đang hưởng trợ cấp hằng tháng từ NSNN', 'Cán bộ xã, phường, thị trấn đã nghỉ việc đang hưởng trợ cấp hằng tháng từ NSNN.');
