INSERT INTO `rule` (`id`, `code`, `display_name`, `description`, `value_hint`, `requires_value`, `is_active`) VALUES
(1, 'REQUIRED', 'Bắt buộc', 'Trường phải tồn tại và không được để trống.', NULL, 0, 1),
(2, 'LENGTH', 'Độ dài chính xác', 'Độ dài của giá trị phải bằng số ký tự cấu hình.', 'Ví dụ: 15', 1, 1),
(3, 'MIN_LENGTH', 'Độ dài tối thiểu', 'Độ dài của giá trị không được nhỏ hơn cấu hình.', 'Ví dụ: 3', 1, 1),
(4, 'MAX_LENGTH', 'Độ dài tối đa', 'Độ dài của giá trị không được lớn hơn cấu hình.', 'Ví dụ: 255', 1, 1),
(5, 'REGEX', 'Biểu thức chính quy', 'Giá trị phải khớp với biểu thức chính quy PHP.', 'Ví dụ: /^\\d{8}$/', 1, 1),
(6, 'NUMERIC', 'Kiểu số', 'Giá trị phải là một số hợp lệ.', NULL, 0, 1),
(7, 'MIN', 'Giá trị tối thiểu', 'Giá trị số không được nhỏ hơn cấu hình.', 'Ví dụ: 0', 1, 1),
(8, 'MAX', 'Giá trị tối đa', 'Giá trị số không được lớn hơn cấu hình.', 'Ví dụ: 100', 1, 1),
(9, 'RANGE', 'Khoảng giá trị', 'Giá trị số phải nằm trong khoảng min,max.', 'Ví dụ: 0,100', 1, 1),
(10, 'IN', 'Thuộc danh sách', 'Giá trị phải thuộc danh sách phân cách bằng dấu phẩy.', 'Ví dụ: 1,2,3', 1, 1),
(11, 'DATE', 'Ngày tháng', 'Giá trị phải đúng định dạng ngày tháng PHP đã cấu hình.', 'Ví dụ: Ymd', 1, 1),
(24, 'FIELD_COMPARE', 'So sánh hai trường', 'So sánh trường hiện tại với một trường trong cùng file hoặc file XML khác.', '{\"other_file_type\":\"XML1\",\"other_field\":\"NGAY_RA\",\"operator\":\"<=\",\"data_type\":\"date\",\"format\":\"YmdHi\"}', 1, 1),
(25, 'API', 'Kiểm tra qua API', 'Gửi path parameters, query parameters hoặc body đến API; hỗ trợ cắt chuỗi trước khi gửi.', '{\"api_config_id\":1,\"request_mapping\":{\"id\":{\"in\":\"path\",\"field\":\"MA_LK\"},\"type\":{\"in\":\"query\",\"value\":\"HS\"},\"ma\":{\"in\":\"body\",\"field\":\"MA_NOI_DEN\"}},\"expected\":true}', 1, 1),
(26, 'SUBSTRING', 'Cắt chuỗi và kiểm tra', 'Cắt một phần giá trị theo vị trí bắt đầu và độ dài, sau đó so sánh với giá trị cấu hình.', '{\"start\":0,\"length\":2,\"operator\":\"=\",\"expected\":\"79\"}', 1, 1),
(27, 'CCCD_GENDER_CENTURY', 'Kiểm tra giới tính và thế kỷ CCCD', 'Đối chiếu ký tự thứ 4 của CCCD với năm sinh và giới tính.', '{\"birth_field\":\"NGAY_SINH\",\"gender_field\":\"GIOI_TINH\",\"male_values\":[\"1\"],\"female_values\":[\"2\"]}', 1, 1),
(29, 'TABLE_EXISTS', 'Tồn tại trong trường', 'Kiểm tra field có tồn tại trong bảng', '{table:icd10,column:code,conditions:{is_active:1}}', 1, 1),
(30, 'NULLABLE', 'Cho phép rỗng/null', 'Cho phép trường không tồn tại, có giá trị null hoặc chuỗi rỗng. Nếu trường có giá trị, các rule khác vẫn được kiểm tra.', '', 0, 1);
