INSERT INTO `xml_validation_rules` (`id`, `file_type`, `field_name`, `display_name`, `rule_type`, `rule_value`, `error_message`, `is_active`) VALUES
(1, 'XML1', 'MA_THE_BHYT', 'Mã bảo hiểm y tế', 'LENGTH', '15', 'Mã thẻ BHYT bắt buộc phải đủ 15 ký tự', 1),
(2, 'XML1', 'HO_TEN', 'Họ và tên', 'REQUIRED', 'NULL', 'Họ tên bệnh nhân không được để trống.', 1),
(3, 'XML1', 'NGAY_SINH', 'Ngày sinh', 'REGEX', '/^\\d{12}$/', 'Ngày sinh phải đúng định dạng 8 số YYYYMMDD.', 1),
(6, 'XML1', 'SO_CCCD', 'Số CCCD', 'LENGTH', '12', 'Sai độ dài mã căn cước công dân (12 số)', 1),
(7, 'XML1', 'NGAY_VAO', 'Ngày vào viện', 'FIELD_COMPARE', '{\n  \"other_file_type\": \"XML1\",\n  \"other_field\": \"NGAY_RA\",\n  \"operator\": \"<=\",\n  \"data_type\": \"date\",\n  \"format\": \"YmdHi\"\n}', 'Ngày ra phải sau ngày vào viện', 1),
(8, 'XML1', 'MA_THE_BHYT', 'Mã thẻ bảo hiểm y tế', 'API', '{\n  \"api_config_id\": 1,\n  \"request_mapping\": {\n    \"ma_the_bhyt\": \"MA_THE_BHYT\",\n    \"ho_ten\": \"HO_TEN\",\n    \"ngay_sinh\": \"NGAY_SINH\"\n  },\n  \"response_field\": \"data.valid\",\n  \"operator\": \"=\",\n  \"expected\": true,\n  \"data_type\": \"boolean\",\n  \"on_error\": \"FAIL\"\n}', 'Thông tin BHYT không hợp lệ', 0),
(10, 'XML1', 'GIOI_TINH', 'Giới tính', 'RANGE', '1,2', 'Lỗi giới tính', 1),
(11, 'XML1', 'MA_NOI_DEN', 'Mã nơi đến', 'IN', '798229', 'Mã nơi đến phải là 798229 ( bệnh viện Thống Nhất)', 0),
(12, 'XML1', 'SO_CCCD', 'căn cước công dân', 'TABLE_EXISTS', '{\"table\":\"ma_tinhthanh\",\"column\":\"ma_cu\",\"value_substring\":{\"start\":0,\"length\":3}}', 'Ba ký tự đầu không phải mã tỉnh phù hợp', 1),
(13, 'XML1', 'MATINH_CU_TRU', 'Mã tỉnh cư trú', 'TABLE_EXISTS', '{\"table\":\"ma_tinhthanh\",\"column\":\"ma_cu\"}', 'Mã tỉnh không tồn tại', 1),
(14, 'XML1', 'SO_CCCD', 'Số căn cước công dân', 'CCCD_GENDER_CENTURY', '{\"birth_field\":\"NGAY_SINH\",\"gender_field\":\"GIOI_TINH\",\"male_values\":[\"1\"],\"female_values\":[\"2\"]}', 'Mã giới tính/thế kỷ trên CCCD không phù hợp với ngày sinh và giới tính.', 1),
(15, 'XML1', 'MA_BENH_CHINH', 'Mã bệnh chính', 'TABLE_EXISTS', '{\n  \"table\": \"icd10\",\n  \"column\": \"code\",\n  \"conditions\": {\n    \"is_active\": 1\n  }\n}', 'Mã ICD10 không tồn tại', 1),
(16, 'XML1', 'KET_QUA_DTRI', 'Kết quả điều trị', 'RANGE', '1,5', 'Kết quả điều trị không hợp lệ', 1),
(17, 'XML1', 'CHAN_DOAN_RV', 'Chẩn đoán', 'MAX_LENGTH', '350', 'Chẩn đoán không quá 350 ký tự', 0),
