(19, 'XML1', 'MAXA_CU_TRU', 'Mã xã cư trú', 'API', '{\n  \"api_config_id\": 5,\n  \"request_mapping\": {\n    \"code\": {\n      \"in\": \"path\",\n      \"field\": \"MAXA_CU_TRU\"\n    }\n  },\n  \"response_field\": \"code\",\n  \"operator\": \">\",\n  \"expected\": 0,\n  \"data_type\": \"number\",\n  \"on_error\": \"FAIL\"\n}', 'mã tỉnh không hợp lệ', 1),
